const a={1:[["1","Yahve, Mısır diyarından çıkışlarının ikinci yılında, ikinci ayın birinci günü, Sina Çölü'nde, Buluşma Çadırı'nda Moşe'yle konuşup şöyle dedi:"],["2","“İsrael'in çocuklarının topluluğunu, soylarına göre, atalarının evlerine göre, adlarının sayısına göre, her erkeği,"],["3","İsrael'de yirmi yaş ve üzeri, savaşa gidebilecek durumda olanların hepsini, sen ve Aron onları bölüklerine göre, birer birer sayacaksınız."],["4","Yanınızda her oymaktan bir adam, her biri atalarının evinin başı olacak."],["5","Sizinle birlikte duracak adamların adları şunlardır: Ruven'den: Şedeur oğlu Elizur."],["6","Şimon'dan: Surişadday oğlu Şelumiel."],["7","Yahuda'dan: Amminadav oğlu Nahşon."],["8","İssakar'dan: Zuar oğlu Netanel."],["9","Zevulun'dan: Helon oğlu Eliav."],["10","Yosef'in çocuklarından: Efraim'den: Ammihud oğlu Elişama; Manaşşe'den: Pedahsur oğlu Gamaliel."],["11","Benyamin'den: Gideoni oğlu Avidan."],["12","Dan'dan: Ammişadday oğlu Ahiezer."],["13","Aşer'den: Okran oğlu Pagiel."],["14","Gad'dan: Deuel oğlu Elyasaf."],["15","Naftali'den: Enan oğlu Ahira.”"],["16","Topluluktan çağrılanlar, atalarının oymaklarının beyleri bunlardır; onlar İsrael binlerinin başlarıydı."],["17","Moşe ile Aron adları anılan bu adamları aldılar."],["18","İkinci ayın birinci günü bütün topluluğu bir araya topladılar; soylarını ailelerine göre, atalarının evlerine göre, ad sayısına göre yirmi yaş ve üzeri olarak teker teker ilan ettiler."],["19","Yahve'nin Moşe'ye buyurduğu gibi onları Sina Çölü'nde saydı."],["20","İsrael'in ilk doğanı Ruven'in çocukları, onların kuşakları, soylarına göre, atalarının evlerine göre, adlarının sayısına göre, yirmi yaş ve üzeri savaşa gidebilecek her erkek, teker teker hepsi:"],["21","Ruven oymağından sayılanlar kırk altı bin beş yüz kişiydi."],["22","Şimon'un çocuklarından, onların kuşakları, soylarına göre, atalarının evlerine göre, adlarının sayısına göre teker teker, onlardan sayılanlar, yirmi yaş ve üzeri savaşa gidebilecek durumda olanların hepsi:"],["23","Şimon oymağından sayılanlar elli dokuz bin üç yüz kişiydi."],["24","Gad'ın çocuklarından, onların kuşakları, soylarına göre, atalarının evlerine göre, adlarının sayısına göre, yirmi yaş ve üzeri savaşa gidebilecek durumda olanlar:"],["25","Gad oymağından sayılanlar kırk beş bin altı yüz elli kişiydi."],["26","Yahuda'nın çocuklarından, onların kuşakları, soylarına göre, atalarının evlerine göre, adlarının sayısına göre, yirmi yaş ve üzeri savaşa gidebilecek durumda olanlar:"],["27","Yahuda oymağından sayılanlar yetmiş dört bin altı yüz kişiydi."],["28","İssakar'ın çocuklarından, onların kuşakları, soylarına göre, atalarının evlerine göre, adlarının sayısına göre, yirmi yaş ve üzeri savaşa gidebilecek durumda olanlar:"],["29","İssakar oymağından sayılanlar elli dört bin dört yüz kişiydi."],["30","Zevulun'un çocuklarından, onların kuşakları, soylarına göre, atalarının evlerine göre, adlarının sayısına göre, yirmi yaş ve üzeri savaşa gidebilecek durumda olanlar:"],["31","Zevulun oymağından sayılanlar elli yedi bin dört yüz kişiydi."],["32","Yosef çocuklarından: Efraim'in çocuklarından, onların kuşakları, soylarına göre, atalarının evlerine göre, adlarının sayısına göre, yirmi yaş ve üzeri savaşa gidebilecek durumda olanlar:"],["33","Efraim oymağından sayılanlar kırk bin beş yüz kişiydi."],["34","Manaşşe'nin çocuklarından, onların kuşakları, soylarına göre, atalarının evlerine göre, adlarının sayısına göre, yirmi yaş ve üzeri savaşa gidebilecek durumda olanlar:"],["35","Manaşşe oymağından sayılanlar otuz iki bin iki yüz kişiydi."],["36","Benyamin'in çocuklarından, onların kuşakları, soylarına göre, atalarının evlerine göre, adlarının sayısına göre, yirmi yaş ve üzeri savaşa gidebilecek durumda olanlar:"],["37","Benyamin oymağından sayılanlar otuz beş bin dört yüz kişiydi."],["38","Dan'ın çocuklarından, onların kuşakları, soylarına göre, atalarının evlerine göre, adlarının sayısına göre, yirmi yaş ve üzeri savaşa gidebilecek durumda olanlar:"],["39","Dan oymağından sayılanlar altmış iki bin yedi yüz kişiydi."],["40","Aşer'in çocuklarından, onların kuşakları, soylarına göre, atalarının evlerine göre, adlarının sayısına göre, yirmi yaş ve üzeri savaşa gidebilecek durumda olanlar:"],["41","Aşer oymağından sayılanlar kırk bir bin beş yüz kişi vardı."],["42","Naftali'nin çocuklarından, onların kuşakları, soylarına göre, atalarının evlerine göre, adlarının sayısına göre, yirmi yaş ve üzeri savaşa gidebilecek durumda olanlar:"],["43","Naftali oymağından sayılanlar elli üç bin dört yüz kişiydi."],["44","Sayılanlar bunlardır; onları Moşe ve Aron'la İsrael'in on iki beyleri saydılar; bunlardan her biri kendi atalarının evi içindi."],["45","Böylece atalarının evlerine göre İsrael'in çocuklarından sayılan yirmi yaş ve üzeri İsrael'de savaşa gidebilecek durumda olanların hepsi,"],["46","sayılanların tamamı altı yüz üç bin beş yüz elli kişiydi."],["47","Ancak Levililer atalarının oymağına göre onların arasında sayılmadı."],["48","Çünkü Yahve Moşe'ye şöyle dedi:"],["49","“Yalnız Levi oymağını saymayacaksın, İsrael'in çocuklarının arasında onların sayımını yapmayacaksın;"],["50","ancak Levililer'i Levha Sandığı'nın, onun tüm takımlarının ve ona ait olan her şeyin üzerinde görevlendir. Konutu ve onun tüm takımlarını onlar taşıyacaklar; onunla onlar ilgilenecekler ve onun çevresinde konaklayacaklar."],["51","Konut taşınacağı zaman Levililer onu indirecekler; ve konut kurulacağı zaman onu Levililer kuracaklar. Yaklaşan yabancı öldürülecektir."],["52","İsrael'in çocukları, kendi bölüklerine göre, herkes kendi ordugâhına ve herkes kendi sancağının yanında çadırlarını kuracaklar."],["53","Ama İsrael'in çocuklarının topluluğu üzerine gazap gelmesin diye Levililer Levha Sandığı'nın çevresinde konaklayacaklar. Levililer Tanıklık Konutu'ndan sorumlu olacaklar.”"],["54","İsrael'in çocukları böyle yaptılar. Yahve'nin Moşe'ye buyurduğu her şeye göre onlar da öyle yaptılar."]],2:[["1","Yahve Moşe ve Aron'la konuşup şöyle dedi:"],["2","“İsrael'in çocukları, herkes kendi bayrağının yanında, atalarının evlerinin sancaklarıyla konaklayacak. Buluşma Çadırı'nın çevresinde, ondan uzakta konaklayacaklar.”"],["3","“Gündoğumuna doğru doğu tarafında konaklayanlar, bölüklerine göre Yahuda ordugâhının bayrağından olacaklar. Yahuda'nın çocuklarının beyi Amminadav oğlu Nahşon olacak."],["4","Onun bölüğü ve onlardan sayılanlar yetmiş dört bin altı yüz kişiydi.”"],["5","“Onun yanında konaklayanlar İssakar oymağı olacak. İssakar'ın çocuklarının beyi Zuar oğlu Netanel olacak."],["6","Onun bölüğü ve ondan sayılanlar elli dört bin dört yüz kişiydi.”"],["7","“Zevulun oymağı: Zevulun'un çocuklarının beyi Helon oğlu Eliav olacak."],["8","Onun bölüğü ve ondan sayılanlar elli yedi bin dört yüz kişiydi.”"],["9","“Yahuda ordugâhından sayılanların hepsi bölüklerine göre yüz seksen altı bin dört yüz kişiydi. İlk olarak onlar yola çıkacaklardır.”"],["10","“Bölüklerine göre Ruven ordugâhının bayrağı güney tarafında olacak. Ruven çocuklarının beyi Şedeur oğlu Elizur olacak.”"],["11","Onun bölüğü ve ondan sayılanlar kırk altı bin beş yüz kişiydi."],["12","“Onun yanında konaklayan Şimon oymağı olacak. Şimon'un çocuklarının beyi Surişadday oğlu Şelumiel olacak."],["13","Onun bölüğü ve ondan sayılanlar elli dokuz bin üç yüz kişiydi.”"],["14","“Gad oymağı: Gad'ın çocuklarının beyi Reuel oğlu Elyasaf olacak."],["15","Onun bölüğü ve ondan sayılanlar kırk beş bin altı yüz elli kişiydi.”"],["16","“Ruven ordugâhından sayılanların hepsi bölüklerine göre yüz elli bir bin dört yüz elli kişiydi. İkinci olarak onlar yola çıkacaklardır.”"],["17","“Sonra Buluşma Çadırı yola çıkacak, Levililer'in ordugâhı ordugâhların ortasında olacak. Konakladıkları gibi, herkes kendi bayraklarına göre, her kişi kendi yerinden yola çıkacak.”"],["18","“Bölüklerine göre Efraim ordugâhının sancağı batı tarafında olacak. Efraim'in çocuklarının beyi Ammihud oğlu Elişama olacak."],["19","Onun bölüğü ve onlardan sayılanlar kırk bin beş yüz kişiydi.”"],["20","“Onun yanında Manaşşe oymağı olacak. Manaşşe'nin çocuklarının beyi Pedahzur oğlu Gamaliel olacak."],["21","Onun bölüğü ve onlardan sayılanlar otuz iki bin iki yüz kişiydi.”"],["22","“Benyamin oymağı: Benyamin'in çocuklarının beyi Gideoni oğlu Avidan olacak."],["23","Onun ordusu ve onlardan sayılanlar otuz beş bin dört yüz kişiydi.”"],["24","“Efraim ordugâhından sayılanların hepsi bölüklerine göre yüz sekiz bin yüz kişiydi. Üçüncü olarak onlar yola çıkacaklardır.”"],["25","“Bölüklerine göre Dan ordugâhının bayrağı kuzey tarafında olacak. Dan'ın çocuklarının beyi Ammişadday oğlu Ahiezer olacak."],["26","Onun bölüğü ve onlardan sayılanlar altmış iki bin yedi yüz kişiydi.”"],["27","“Onun yanında konaklayanlar Aşer oymağı olacak. Aşer'in çocuklarının beyi Okran oğlu Pagiel olacak."],["28","Onun bölüğü ve onlardan sayılanlar kırk bir bin beş yüz kişiydi.”"],["29","“Naftali oymağı: Naftali'nin çocuklarının beyi Enan oğlu Ahira olacak."],["30","Onun bölüğü ve onlardan sayılanlar elli üç bin dört yüz kişiydi.”"],["31","“Dan ordugâhından sayılanların hepsi yüz elli yedi bin altı yüz kişiydi. Kendi bayraklarına göre en son onlar yola çıkacaklardır.”"],["32","Bunlar atalarının evlerine göre İsrael'in çocuklarından sayılanlardır. Ordularına göre ordugâhlardan sayılanların hepsi altı yüz üç bin beş yüz elli kişiydi."],["33","Ancak Yahve'nin Moşe'ye buyurmuş olduğu gibi Levililer İsrael'in çocukları arasında sayılmadılar."],["34","İsrael'in çocukları da böyle yaptı. Yahve'nin Moşe'ye buyurduğu her şeye göre, kendi bayraklarına göre konakladılar ve böylece herkes aileleri ile atalarının evlerine göre yola çıktılar."]],3:[["1","Yahve'nin Sina Dağı'nda Moşe'yle konuştuğu gün Aron'la Moşe'nin soylarının tarihi şöyledir."],["2","Aron'un oğullarının adları şunlardır: İlk doğan Nadav, Avihu, Eleazar ve İtamar."],["3","Aron'un oğullarının, kâhinlik makamında hizmet etmek üzere adadığı, meshedilmiş kâhinlerin adları bunlardır."],["4","Nadav ile Avihu, Sina Çölü'nde Yahve'nin önünde yabancı ateş sundukları zaman Yahve'nin önünde öldüler; onların çocukları yoktu. Eleazar ve İtamar, babaları Aron'un önünde kâhinlik makamında hizmet ettiler."],["5","Yahve Moşe'ye şöyle konuştu:"],["6","“Levi oymağını yaklaştır ve onları kâhin Aron'un önünde, ona hizmet etsinler diye durdur."],["7","Konutun hizmetini yapmak üzere onun ve tüm topluluğun gereksinimlerini Buluşma Çadırı'nın önünde onlar sağlayacaklar."],["8","Buluşma Çadırı'nın bütün takımlarını ve İsrael'in çocuklarının konut hizmetiyle ilgili yükümlülüklerini onlar karşılayacak."],["9","Levililer'i Aron'la oğullarına vereceksin. Onlar İsrael'in çocukları adına tamamen ona verilmiştir."],["10","Aron'la oğullarını sen atayacaksın, onlar da kâhinliklerini sürdürecekler, yaklaşan yabancı ise öldürülecektir.”"],["11","Yahve Moşe'ye şöyle dedi:"],["12","“İşte, İsrael'in çocukları arasında rahmi açan ilk doğanların yerine, Levililer'i İsrael'in çocukları arasından seçtim; ve Levililer benim olacak."],["13","Çünkü ilk doğanların hepsi benimdir. Mısır diyarında bütün ilk doğanları vurduğum gün, İsrael'de insan olsun hayvan olsun bütün ilk doğanları kendime kutsal kıldım. Benim olacaklar. Ben Yahve'yim.”"],["14","Yahve Sina Çölü'nde Moşe'ye şöyle dedi:"],["15","“Levi çocuklarını atalarının evlerine, ailelerine göre say. Bir aylık ve üstü olan her erkeği sayacaksın.”"],["16","Moşe onları Yahve'nin sözüne göre, kendisine buyurulduğu gibi saydı."],["17","Levi'nin oğulları adlarıyla şunlardır: Gerşon, Kehat ve Merari."],["18","Gerşon'un oğullarının ailelerine göre adları şunlardır: Livni ve Şimi."],["19","Ailelerine göre Kohat'ın oğulları: Amram, Yishar, Hevron ve Uzziel."],["20","Ailelerine göre Merari'nin oğulları: Mahli ve Muşi. Babalarının evlerine göre Levililer'in aileleri bunlardır."],["21","Livnî ailesi ve Şimi ailesi Gerşon'dandı. Bunlar Gerşonlular'ın aileleridir."],["22","Onlardan sayılanlar, bir aylık ve üstü olan tüm erkeklerin sayısına göre yedi bin beş yüz kişiydi."],["23","Gerşonlular'ın aileleri konutun arkasında batıya doğru konaklayacaklar."],["24","Lael oğlu Elyasaf Gerşonlular'ın atalar evinin beyi olacak."],["25","Buluşma Çadırı'nda Gerşon oğullarının görevi konut, çadır, onun örtüsü, Buluşma Çadırı'nın kapı perdesi,"],["26","konutla sunağın çevresindeki avlunun perdeleri, avlu kapısının perdesi ve bütün hizmeti için onun ipleri olacaktır."],["27","Amramlılar'ın ailesi, Yisharlılar'ın ailesi, Hevronlular'ın ailesi ve Uzzielliler'in ailesi Kohat'tandı."],["28","Bir aylık ve üstü olan tüm erkeklerin sayısına göre, kutsal yerin gereksinimlerini karşılayan sekiz bin altı yüz kişi vardı."],["29","Kohatoğulları'nın aileleri konutun güney tarafında konaklayacaklar."],["30","Kohatlılar'ın ailelerinin atalar evi beyi Uzziel oğlu Elizafan olacak."],["31","Sandık, masa, şamdan, sunaklar, hizmet ettikleri kutsal yerin takımları, perde ve onun tüm hizmeti onların görevi olacak."],["32","Kâhin Aron'un oğlu Eleazar, kutsal yerin gereksinimlerini sağlayanların üzerinde Levili beylerin beyi olacak."],["33","Mahlitliler ailesi ve Muşililer ailesi Merari'dendi. Bunlar Merari'nin aileleridir."],["34","Bir aylık ve daha üstü olan tüm erkeklerin sayısına göre onlardan sayılanlar altı bin iki yüz kişiydi."],["35","Merari ailelerinin atalar evinin beyi Avihail oğlu Suriel'di. Onlar konutun kuzey tarafında konaklayacaklar."],["36","Merarioğulları'nın belirlenmiş görevleri konutun çerçeveleri, kirişleri, direkleri, tabanları, bütün takımları, onun tüm hizmetleri,"],["37","çevresindeki avlunun direkleri, tabanları, kazıkları ve ipleridir."],["38","Doğuya doğru konutun önünde, güneşin doğduğu yere doğru Buluşma Çadırı'nın önünde, İsrael'in çocuklarının görevi için kutsal yerin gereksinimlerini karşılamak üzere konaklayanlar, Moşe, Aron ve oğulları olacaklar. Yaklaşan yabancı öldürülecektir."],["39","Moşe ile Aron'un Yahve'nin buyruğu uyarınca ailelerine göre saydıkları Levililer'in tümü, bir aylık ve üstü olan tüm erkekler yirmi iki bin kişiydi."],["40","Yahve Moşe'ye şöyle dedi: “İsrael'in çocuklarından bir aylık ve üstü olan ilk doğan tüm erkekleri say ve adlarının sayısını al."],["41","İsrael'in çocukları arasında ilk doğanların yerine Levililer'i, —Ben Yahve'yim—benim için alacaksın; ve İsrael'in çocuklarının hayvanları arasında bütün ilk doğanlar yerine Levililer'in hayvanlarını alacaksın.”"],["42","Moşe, Yahve'nin kendisine buyurduğu gibi, İsrael'in çocukları arasında ilk doğanların hepsini saydı."],["43","Ad sayısına, bir aylık ve üstü olanlardan sayılanlara göre ilk doğan bütün erkekler yirmi iki bin iki yüz yetmiş üç kişiydi."],["44","Yahve Moşe'ye şöyle dedi:"],["45","“İsrael'in çocukları arasında ilk doğanların tümü yerine Levililer'i, onların hayvanları yerine de Levililer'in hayvanlarını al; Levililer de benim olacak. Ben Yahve'yim."],["46","İsrael'in çocuklarının ilk doğanlarından Levililer'in sayısını aşan iki yüz yetmiş üç kişinin bedeli için,"],["47","kişi başına beş şekel alacaksın; onları kutsal yerin şekeline göre alacaksın (şekel yirmi geradır);"],["48","ve onlardan geri kalan bedel parasını Aron'la oğullarına vereceksin.”"],["49","Moşe, Levililer'le bedeli verilmiş olanları aşanların bedel parasını aldı;"],["50","İsrael'in çocuklarının ilk doğanlarından kutsal yerin şekeline göre bin üç yüz altmış beş şekel para aldı;"],["51","Yahve'nin sözü uyarınca Moşe, Yahve'nin Moşe'ye buyurduğu gibi bedel parasını Aron'la oğullarına verdi."]],4:[["1","Yahve Moşe ve Aron'la konuşup şöyle dedi:"],["2","“Levioğulları arasından Kohat'ın oğullarını, ailelerine, ata evlerine göre,"],["3","otuz yaştan başlayarak elli yaşına kadar Buluşma Çadırı'nda iş yapmak üzere hizmete girenlerin tümünü sayın.”"],["4","“Buluşma Çadırı'nda Kohatoğulları'nın en kutsal şeylerle ilgili hizmeti budur."],["5","Ordugâh göç edince Aronoğulları'yla birlikte içeri girecek ve bölme perdesini indirecekler, Levha Sandığı'nı onunla örtecekler,"],["6","üzerine fok derisinden bir örtü koyacaklar, üzerine mavi bir bez serip sırıklarını takacaklar.”"],["7","“Sergi ekmeği masasının üzerine mavi bir bez serip üzerine tabakları, kaşıkları, kâseleri, dökmelik sunu için tasları koyacaklar; ve sürekli ekmek onun üzerinde olacak."],["8","Üzerlerine kırmızı bir bez serip onu fok derisinden bir örtüyle örtecekler ve sırıklarını takacaklar.”"],["9","“Lacivert bir bez alıp ışık veren şamdanı, kandillerini, makaslarını, tablalarını ve onun hizmetinde kullanılan tüm yağ kaplarını örtecekler."],["10","Onu ve içindeki tüm takımlarını fok derisinden bir örtü içine koyacaklar ve onu sedye üzerine koyacaklar.”"],["11","“Altın sunağın üzerine mavi bir bez serip onu deri bir örtüyle örtecekler ve sırıklarını geçirecekler.”"],["12","“Kutsal yerde hizmet ettikleri bütün hizmet takımlarını alıp mavi bir beze saracaklar, üzerini fok derisinden bir örtüyle örtecekler ve sedye üzerine koyacaklar.”"],["13","“Sunağın küllerini kaldırıp üzerine mor bir bez serecekler."],["14","Onun üzerinde hizmet için kullanılan tüm takımları, ateş tavalarını, et kancalarını, kürekleri ve leğenleri, sunağın tüm takımlarını onun üzerine koyacaklar; ve üzerine fok derisinden bir örtü serip sırıklarını geçirecekler.”"],["15","“Aron'la oğulları kutsal yeri ve kutsal yerin tüm takımlarını örtmeyi bitirince, ordugâh göç ederken; ondan sonra Kohat'ın oğulları onu taşımaya gelecekler; ama ölmesinler diye kutsal yere dokunmayacaklar. Buluşma Çadırı'na ait olan bu şeyleri Kohat'ın oğulları taşıyacak.”"],["16","“Kâhin Aron oğlu Eleazar'ın görevi, ışık için yağ, kokulu buhur, sürekli ekmek sunusu, mesh yağı, tüm konutun, ve içinde bulunan her şeyin, kutsal yer ve onun takımlarının gereksinimleri olacak.”"],["17","Yahve Moşe ve Aron'la konuşup şöyle dedi:"],["18","“Kohatlı ailelerin boyunu Levililer arasından ayırmayın;"],["19","ama onlara şöyle yapın ki, çok kutsal şeylere yaklaştıklarında ölmesinler, yaşasınlar. Aron'la oğulları içeri girecekler ve herkesi kendi hizmetine ve yüküne atayacaklar;"],["20","ama ölmemek için bir an bile kutsal yeri görmeye girmeyecekler.”"],["21","Yahve Moşe'ye şöyle dedi:"],["22","“Gerşon'un oğullarını da atalarının evlerine, ailelerine göre say;"],["23","onları, otuz yaşından elli yaşına kadar Buluşma Çadırı'nda hizmete hazır, iş yapmak üzere içeri girenlerin hepsini sayacaksın.”"],["24","“Gerşonlu ailelerin hizmet ve yük taşımakta hizmeti şudur:"],["25","Konutun perdelerini ve Buluşma Çadırı'nı ve onun üstündeki fok derisinden örtüyü, Buluşma Çadırı'nın kapı perdesini,"],["26","avlunun perdelerini, konutun yanındaki ve sunağın çevresindeki avlu kapısının kapı perdesi, bunların ipleri, onların hizmetinde kullanılan bütün aletleri onlar taşıyacaklar; onlarla yapılan her işte onlar hizmet edecekler."],["27","Gerşon'un oğullarının bütün hizmetinde, tüm yükleri ve tüm hizmetleri Aron'la oğullarının buyruğuyla olacak; ve tüm sorumluluklarında onlara görev atayacaksın."],["28","Gerşonlu oğulları ailelerinin Buluşma Çadırı'ndaki hizmeti budur. Görevleri kâhin Aron oğlu İtamar'ın eli altında olacaktır.”"],["29","“Merari'nin oğullarına gelince, onları ailelerine, atalarının evlerine göre sayacaksın;"],["30","Buluşma Çadırı'nın işini yapmak üzere hizmete giren herkesi otuz yaşından elli yaşına kadar sayacaksın."],["31","Buluşma Çadırı'nda yaptıkları tüm hizmete göre onların yükleri şunlardır: Bütün takımları ve bütün hizmetleriyle birlikte, konutun çerçeveleri, kirişleri, direkleri, tabanları,"],["32","çevresindeki avlunun direkleri, bunların tabanları, kazıkları, ipleridir. Yüklerinin görev aletlerini adlarıyla onlara atayacaksınız."],["33","Merarioğulları ailelerinin, Kâhin Aron oğlu İtamar'ın eli altında Buluşma Çadırı'nda yaptıkları bütün hizmetlerine göre hizmeti budur.”"],["34","Moşe, Aron ve topluluğun beyleri, Kohatlıoğulları'nı ailelerine ve atalarının evlerine göre;"],["35","otuz yaşından elli yaşına kadar, Buluşma Çadırı'nda çalışmak üzere hizmete giren herkesi saydılar."],["36","Ailelerine göre onlardan sayılanlar iki bin yedi yüz elli kişiydi."],["37","Buluşma Çadırı'nda hizmet eden Kohatlı ailelerden sayılanlar bunlardı; Yahve'nin Moşe aracılığıyla verdiği buyruk uyarınca Moşe ile Aron'un saydıkları onlardı."],["38","Ailelerine ve atalarının evlerine göre Gerşon'un oğulları arasında sayılanlar,"],["39","otuz yaşından elli yaşına kadar, Buluşma Çadırı'nda çalışmak üzere hizmete giren hepsi,"],["40","ailelerine ve atalarının evlerine göre onlardan sayılanlar iki bin altı yüz otuz kişiydi."],["41","Moşe ve Aron'un Yahve'nin buyruğu uyarınca saydıkları, Buluşma Çadırı'nda hizmet eden Gerşon'un oğullarının ailelerinden sayılanlar bunlardı."],["42","Ailelerine ve atalarının evlerine göre Merarioğulları ailelerinden sayılanlar,"],["43","otuz yaşından elli yaşına kadar, Buluşma Çadırı'nda çalışmak üzere hizmete giren herkes;"],["44","ailelerine göre onlardan sayılanlar üç bin iki yüz kişiydi."],["45","Bunlar, Yahve'nin Moşe aracılığıyla verdiği buyruğa göre Moşe ile Aron'un saydıkları Merarioğulları ailelerinden sayılanlardı."],["46","Moşe, Aron ve İsrael beylerinin ailelerine ve atalarının evlerine göre saydıkları Levililer arasında sayılanlar,"],["47","otuz yaşından elli yaşına kadar hizmet işini ve Buluşma Çadırı'nda yükler taşıma işini yapmak için girenlerin hepsi,"],["48","onlardan sayılanlar sekiz bin beş yüz seksen kişiydi."],["49","Yahve'nin buyruğu uyarınca, herkes kendi hizmetine ve yüküne göre Moşe tarafından sayıldı. Böylece Yahve'nin Moşe'ye buyurduğu gibi onlar onun tarafından sayıldılar."]],5:[["1","Yahve Moşe'ye şöyle dedi:"],["2","“İsrael'in çocuklarına buyur, her cüzamlıyı, her akıntısı olanı ve ölüden dolayı kirli olan her kişiyi ordugâhtan çıkarsınlar."],["3","Ortasında oturduğum ordugâhı kirletmesinler diye, hem erkekleri hem de kadınları ordugâhın dışına çıkaracaksınız.”"],["4","İsrael'in çocukları da öyle yaptılar ve onları ordugâhın dışına çıkardılar; Yahve Moşe'ye nasıl söylediyse, İsrael'in çocukları da öyle yaptı."],["5","Yahve Moşe'ye şöyle konuştu:"],["6","“İsrael'in çocuklarına de ki: 'Bir erkek ya da kadın, Yahve'ye karşı gelerek, insanların işlediği günahlardan birisini işlediğinde ve o can suçlu olduğunda,"],["7","o zaman işlemiş olduğu günahı itiraf edecek; ve suçunun karşılığını tamamen ödeyecek, üzerine beşte birini ekleyecek ve onu suçlu olduğu insana verecektir."],["8","Ancak eğer suçun karşılığını ödemek için o adamın yakın akrabası yoksa, kendisi için kefaret edecek olan kefaret koçunun yanı sıra, Yahve'ye ödenen suç karşılığı da kâhinin olacaktır."],["9","İsrael'in çocuklarının kâhine sundukları tüm kutsal şeylerden her kaldırma sunusu onun olacak."],["10","Herkesin kutsal şeyleri onun olacaktır; kim kâhine bir şey verirse, onun olacaktır.'”"],["11","Yahve Moşe'ye şöyle konuştu:"],["12","“İsrael'in çocuklarına söyle ve onlara de: 'Bir adamın karısı yoldan sapar ve ona sadakatsizlik ederse,"],["13","bir erkek onunla yatar, bu kocasının gözlerinden gizlenir ve saklı kalırsa, ve kadın kirlenir, ona karşı hiçbir tanık yoksa, kadın eylem sırasında tutulmazsa;"],["14","adamın üzerine kıskançlık ruhu gelir, karısı kirli olduğu halde karısını kıskanırsa; ya da eğer adamın üzerine kıskançlık ruhu gelir ve karısı kirli olmadığı halde karısını kıskanırsa;"],["15","o zaman adam karısını kâhine getirecek ve onun için sunu olarak onda bir efa arpa unu getirecek. Üzerine yağ dökmeyecek ve üzerine buhur koymayacak; çünkü bu kıskançlık ekmeği sunusu, kötülüğü hatırlatan anma ekmek sunusudur."],["16","Kâhin kadını yaklaştırıp Yahve'nin önünde durduracak."],["17","Kâhin kutsal suyu toprak bir kap içine alacak; ve kâhin konutun zemini üzerindeki tozun bir kısmını alıp suya koyacak."],["18","Kâhin kadını Yahve'nin önünde durduracak, kadının saçlarını çözecek ve anma ekmek sunusunu onun ellerine koyacak, kıskançlık ekmek sunusudur. Kâhinin elinde lanet getiren acılık suyu olacak."],["19","Kâhin ona ant içirtip kadına şöyle diyecek: “Eğer seninle bir erkek yatmamışsa ve kocanın yetkisi altında kirliliğe sapmadıysan, lanet getiren bu acılık suyundan kurtul."],["20","Ama eğer kocanın yetkisi altındayken yoldan sapmışsan, kirlenmişsen ve kocandan başka bir adam seninle yatmışsa…”"],["21","o zaman kâhin kadına lanet andı içirtip kâhin kadına şöyle diyecek: “Yahve kalçanın düşmesine ve vücudunun şişmesine izin verdiğinde, Yahve seni halkının arasında bir lanet ve küfür yapsın;"],["22","lanet getiren bu su bağırsaklarına girecek, vücudunu şişirecek, kalçanı düşürecek.'' Kadın “Amin, Amin” diyecek.'”"],["23","“'Kâhin bu lanetleri bir kitaba yazacak ve onları acılık suyu içinde silecek."],["24","Lanet getiren acılık suyunu kadına içirecek; ve lanete neden olan su onun içine girecek ve acılaşacak."],["25","Kâhin kıskançlık ekmek sunusunu kadının elinden alacak ve ekmek sunusunu Yahve'nin önünde sallayacak ve onu sunağa getirecek."],["26","Kâhin anma payı olarak ekmek sunusundan bir avuç alacak, onu sunakta yakacak, sonra da suyu kadına içirecek."],["27","O, suyu ona içirdiğinde, eğer kadın kirlenmişse ve kocasına karşı bir suç işlemişse, lanete neden olan su onun içine girecek ve acılaşacak, vücudu şişecek ve kalçası düşecek; kadın da halkı arasında bir lanet olacaktır."],["28","Eğer kadın kirli değilse ama temizse; o zaman kurtulacak ve soy sahibi olacaktır.'”"],["29","“'Kocasına bağlı kadın yoldan sapıp kirlendiğinde,"],["30","ya da kıskançlık ruhu erkeğin üzerine geldiğinde ve karısını kıskandığında kıskançlık yasası budur; o zaman kadını Yahve'nin önünde durduracak ve kâhin bu yasanın tamamını onun üzerinde uygulayacaktır."],["31","Erkek kötülükten özgür olacak, o kadın da kendi kötülüğünü taşıyacaktır.'”"]],6:[["1","Yahve Moşe'ye şöyle dedi:"],["2","“İsrael'in çocuklarına konuş ve onlara şunu söyle: 'Erkek ya da kadın, kendini Yahve'ye ayırmak için özel bir adak, yani bir Neziri adağı adarsa,"],["3","kendini şaraptan ve ağır içkiden ayrı tutacak. Şarap sirkesi ya da mayalanmış içecek sirkesi içmeyecek, hiç üzüm suyu içmeyecek, taze üzüm ya da kurutulmuş üzüm yemeyecektir."],["4","Ayrıldığı günler boyunca, çekirdeklerinden kabuğuna kadar asmadan yapılan hiçbir şeyi yemeyecektir."],["5","“'Ayrılık adağı günleri boyunca, kendisini Yahve'ye ayıracağı günler doluncaya dek başına ustura gelmeyecek. O kutsal olacaktır. Başındaki saçlarını uzatacaktır."],["6","“'Yahve'ye ayrıldığı günler boyunca ölünün yanına yaklaşmayacak."],["7","Babası, annesi, erkek kardeşi ya da kız kardeşi öldüğü zaman onlar için kendini kirletmeyecektir; çünkü Tanrı'ya ayrılması onun başı üzerindedir."],["8","Ayrıldığı günler boyunca Yahve'ye kutsaldır."],["9","“'Eğer bir kişi aniden onun yanında ölürse ve ayrılığının başını kirletirse, o zaman temizlendiği gün başını tıraş edecek. Yedinci gün onu tıraş edecek."],["10","Sekizinci gün kâhine, Buluşma Çadırı'nın kapısına iki kumru ya da iki güvercin yavrusu getirecek."],["11","Kâhin birini günah sunusu, diğerini yakmalık sunu olarak sunacak ve ölü yüzünden günah işlediği için onun için kefaret edecek ve aynı gün başını kutsal kılacaktır."],["12","Ayrılık günlerini Yahve'ye ayıracak ve suç sunusu olarak bir yaşında bir erkek kuzu getirecek; ancak önceki günler boşa gidecektir, çünkü onun ayrılığı kirlenmiştir."],["13","“'Nezir'in yasası şudur: Ayrılık günleri tamamlanınca, Buluşma Çadırı'nın kapısına getirilecek."],["14","Yahve'ye yakmalık sunu olarak kusursuz bir yaşında, erkek kuzu, günah sunusu olarak kusursuz bir yaşında dişi kuzu, esenlik sunuları olarak kusursuz bir koç,"],["15","bir sepet mayasız ekmek, yağla yoğrulmuş ince undan pideler ve onların ekmek sunusuyla ve onların dökmelik sunusuyla birlikte yağ sürülmüş mayasız yufkalar sunacaktır."],["16","Kâhin bunları Yahve'nin önüne çıkaracak, günah sunusunu ve yakmalık sunusunu sunacak."],["17","Koçu, mayasız ekmek sepetiyle birlikte Yahve'ye esenlik sunuları kurbanı olarak sunacak. Kâhin ayrıca onun ekmek sunusunu ve dökmelik sunusunu da sunacak."],["18","Nezir, ayrılığının başını Buluşma Çadırı'nın kapısında tıraş edecek, ayrılık başının saçını alıp esenlik sunuları kurbanının altındaki ateşin üzerine koyacak."],["19","Kâhin koçun haşlanmış omzunu, bir mayasız pideyi ve bir mayasız yufkayı sepetten çıkarıp Nezir'in başını tıraş ettikten sonra bunları onun ellerine koyacak;"],["20","ve kâhin bunları Yahve'nin önünde sallamalık sunu olarak sallayacak. Sallanan döş ve sunulan butla birlikte bunlar kâhin için kutsaldır. Bundan sonra Nezir şarap içebilir."],["21","“'Adak adayan Neziri'nin, gücünün yettiği diğer şeylerin yanı sıra, ayrılığı için Yahve'ye sunusunun yasası budur. Adadığı adak uyarınca, kendi ayrılığının yasasına göre böyle yapmalıdır.'”"],["22","Yahve Moşe'ye şöyle konuştu:"],["23","“Aron'la ve oğullarıyla konuş ve şöyle de: İsrael'in çocuklarını böyle kutsayacaksınız. Onlara diyeceksiniz:"],["24","'Yahve sizi kutsasın ve korusun."],["25","Yahve yüzünü sizin üzerinizde ışıldatsın ve size lütfetsin."],["26","Yahve yüzünü size doğru kaldırsın ve size esenlik versin.'"],["27","“Böylece İsrael'in çocukları üzerine adımı koyacaklar; ve ben onları kutsayacağım.”"]],7:[["1","Moşe konutu kurmayı bitirdiği, onu meshettiği, tüm takımlarıyla birlikte, sunağı da tüm eşyalarıyla birlikte kutsadığı ve onları mesh edip kutsadığı gün;"],["2","atalarının evlerinin başları olan İsrael beyleri sunular sundular. Bunlar oymakların beyleriydi. Bunlar, sayılanların başında olanlardı;"],["3","her iki beye bir araba ve her birine bir öküz olmak üzere, Yahve'nin önüne sunularını altı kapalı araba ve on iki öküz getirdiler. Bunları konutun önünde takdim ettiler."],["4","Yahve Moşe'ye şöyle konuştu:"],["5","“Buluşma Çadırı'nın hizmetinde kullanılmak üzere bunları onlardan al; ve bunları her adama hizmetine göre Levililer'e vereceksin.”"],["6","Moşe arabaları ve öküzleri alıp Levililer'e verdi."],["7","Yaptıkları hizmete göre Gerşon'un oğullarına iki araba ve dört öküz verdi."],["8","Kâhin Aron oğlu İtamar'ın yönetimi altında Merari'nin oğullarına hizmetlerine göre dört araba ve sekiz öküz verdi."],["9","Ancak Kohat'ın oğullarına hiçbir şey vermedi; çünkü kutsal yerin hizmeti onlara aitti; onu omuzlarında taşırlardı."],["10","Beyler sunağın meshedildiği gün onun adanması için sunular sundular. Beyler sunağın önünde sunularını sundular."],["11","Yahve Moşe'ye şöyle dedi: “Sunağın adanması için her bey kendi gününde kendi sunularını sunacaklar.”"],["12","İlk gün sunusunu sunan kişi Yahuda oymağından Amminadav oğlu Nahşon'du,"],["13","onun sunusu şunlardı: Kutsal yerin şekeline göre, ağırlığı yüz otuz şekel olan bir gümüş tepsi, yetmiş şekellik bir gümüş tas; bunların her ikisi de ekmek sunusu için yağla yoğrulmuş ince unla doluydu;"],["14","buhurla dolu on şekellik altın bir kepçe;"],["15","yakmalık sunu için bir genç boğa, bir koç ve bir yaşında bir erkek kuzu;"],["16","günah sunusu olarak bir teke;"],["17","esenlik kurbanı olarak iki sığır, beş koç, beş teke ve bir yaşında beş erkek kuzu. Bu, Amminadav oğlu Nahşon'un sunusuydu."],["18","İkinci gün sunusunu sunan İssakar beyi Suar oğlu Netanel'di."],["19","Sunusu olarak şunları sundu: Ağırlığı yüz otuz şekel olan bir gümüş tepsi, kutsal yerin şekeline göre yetmiş şekellik bir gümüş tas; bunların her ikisi de ekmek sunusu için yağla yoğrulmuş ince unla doluydu;"],["20","buhurla dolu, on şekellik altın bir kepçe;"],["21","yakmalık sunu olarak bir genç boğa, bir koç ve bir yaşında bir erkek kuzu;"],["22","günah sunusu olarak bir teke;"],["23","esenlik kurbanı olarak iki sığır, beş koç, beş teke, bir yaşında beş erkek kuzu. Bu, Suar oğlu Netanel'in sunusuydu."],["24","Üçüncü gün Zevulunoğulları'nın beyi Helon oğlu Eliav sunusunu sundu:"],["25","Ağırlığı yüz otuz şekel olan bir gümüş tepsi, kutsal yerin şekeline göre yetmiş şekellik bir gümüş tas; bunların her ikisi de ekmek sunusu için yağla yoğrulmuş ince unla doluydu;"],["26","buhurla dolu, on şekellik altın bir kepçe;"],["27","yakmalık sunu olarak bir genç boğa, bir koç ve bir yaşında bir erkek kuzu;"],["28","günah sunusu olarak bir teke;"],["29","esenlik kurbanı olarak iki sığır, beş koç, beş teke ve bir yaşında beş erkek kuzu. Bu, Helon oğlu Eliav'ın sunusuydu."],["30","Dördüncü gün Ruvenoğulları beyi Şedeur oğlu Elizur sunusunu sundu:"],["31","Ağırlığı yüz otuz şekel olan bir gümüş tepsi, kutsal yerin şekeline göre yetmiş şekellik bir gümüş tas; bunların her ikisi de ekmek sunusu için yağla yoğrulmuş ince unla doluydu;"],["32","buhurla dolu, on şekellik altın bir kepçe;"],["33","yakmalık sunu için bir genç boğa, bir koç ve bir yaşında bir erkek kuzu;"],["34","günah sunusu olarak bir teke;"],["35","esenlik kurbanı olarak iki sığır, beş koç, beş teke ve bir yaşında beş erkek kuzu. Bu, Şedeur oğlu Elizur'un sunusuydu."],["36","Beşinci gün Şimonoğulları beyi Surişadday oğlu Şelumiel sunusunu sundu:"],["37","Ağırlığı yüz otuz şekel olan bir gümüş tepsi, kutsal yerin şekeline göre yetmiş şekellik bir gümüş tas; bunların her ikisi de ekmek sunusu için yağla yoğrulmuş ince unla doluydu;"],["38","buhurla dolu on şekellik altın bir kepçe;"],["39","yakmalık sunu olarak bir genç boğa, bir koç ve bir yaşında bir erkek kuzu;"],["40","günah sunusu için bir teke;"],["41","esenlik kurbanı için iki sığır, beş koç, beş teke ve bir yaşında beş erkek kuzu; bu, Surişadday oğlu Şelumiel'in sunusuydu."],["42","Altıncı gün, Gadoğulları'nın beyi Deuel oğlu Elyasaf sunusunu sundu:"],["43","Ağırlığı yüz otuz şekel olan bir gümüş tepsi, kutsal yerin şekeline göre yetmiş şekellik bir gümüş tas; bunların her ikisi de ekmek sunusu için yağla yoğrulmuş ince unla doluydu;"],["44","buhurla dolu, on şekellik altın bir kepçe;"],["45","yakmalık sunu olarak bir genç boğa, bir koç ve bir yaşında bir erkek kuzu;"],["46","günah sunusu olarak bir teke;"],["47","esenlik kurbanı olarak iki sığır, beş koç, beş teke ve bir yaşında beş erkek kuzu. Bu, Deuel oğlu Elyasaf'ın sunusuydu."],["48","Yedinci gün Efraimoğulları beyi Ammihud oğlu Elişama sunusunu sundu:"],["49","Ağırlığı yüz otuz şekel olan bir gümüş tepsi, kutsal yerin şekeline göre yetmiş şekellik bir gümüş tas; bunların her ikisi de ekmek sunusu için yağla yoğrulmuş ince unla doluydu;"],["50","buhurla dolu, on şekellik bir altın kepçe;"],["51","yakmalık sunu olarak bir genç boğa, bir koç ve bir yaşında bir erkek kuzu;"],["52","günah sunusu olarak bir teke;"],["53","esenlik kurbanı olarak iki sığır, beş koç, beş teke ve bir yaşında beş erkek kuzu. Bu, Ammihud oğlu Elişama'nın sunusuydu."],["54","Sekizinci gün Manaşşeoğulları beyi Pedahzur oğlu Gamaliel sunusunu sundu:"],["55","Ağırlığı yüz otuz şekel olan bir gümüş tepsi, kutsal yerin şekeline göre yetmiş şekellik bir gümüş tas; bunların her ikisi de ekmek sunusu için yağla yoğrulmuş ince unla doluydu;"],["56","buhurla dolu, on şekellik altın bir kepçe;"],["57","yakmalık sunu için bir genç boğa, bir koç, bir yaşında bir erkek kuzu;"],["58","günah sunusu için bir teke;"],["59","esenlik kurbanı olarak iki sığır, beş koç, beş teke ve bir yaşında beş erkek kuzu. Bu, Pedahzur oğlu Gamaliel'in sunusuydu."],["60","Dokuzuncu gün Benyaminoğulları beyi Gideoni oğlu Avidan sunusunu sundu:"],["61","Ağırlığı yüz otuz şekel olan bir gümüş tepsi, kutsal yerin şekeline göre yetmiş şekellik bir gümüş tas; bunların her ikisi de ekmek sunusu için yağla yoğrulmuş ince unla doluydu;"],["62","buhurla dolu, on şekellik altın bir kepçe;"],["63","yakmalık sunu için bir genç boğa, bir koç, bir yaşında bir erkek kuzu;"],["64","günah sunusu için bir teke;"],["65","esenlik kurbanı olarak iki sığır, beş koç, beş teke ve bir yaşında beş erkek kuzu. Bu, Gideoni oğlu Avidan'ın sunusuydu"],["66","Onuncu gün Danoğulları beyi Ammişadday oğlu Ahiezer sunusunu sundu:"],["67","Ağırlığı yüz otuz şekel olan bir gümüş tepsi, kutsal yerin şekeline göre yetmiş şekellik bir gümüş tas; bunların her ikisi de ekmek sunusu için yağla yoğrulmuş ince unla doluydu;"],["68","buhurla dolu, on şekellik altın bir kepçe;"],["69","yakmalık sunu için bir genç boğa, bir koç, bir yaşında bir erkek kuzu;"],["70","günah sunusu için bir teke;"],["71","esenlik kurbanı olarak iki sığır, beş koç, beş teke ve bir yaşında beş erkek kuzu. Bu, Ammişadday oğlu Ahiezer'in sunusuydu."],["72","On birinci gün Aşeroğulları beyi Okran oğlu Pagiel sunusunu sundu:"],["73","Ağırlığı yüz otuz şekel olan bir gümüş tepsi, kutsal yerin şekeline göre yetmiş şekellik bir gümüş tas; bunların her ikisi de ekmek sunusu için yağla yoğrulmuş ince unla doluydu;"],["74","buhurla dolu, on şekellik altın bir kepçe;"],["75","yakmalık sunu için bir genç boğa, bir koç, bir yaşında bir erkek kuzu;"],["76","günah sunusu için bir teke;"],["77","esenlik kurbanı olarak iki sığır, beş koç, beş teke ve bir yaşında beş erkek kuzu. Bu, Okran oğlu Pagiel'in sunusuydu."],["78","On ikinci gün Naftalioğulları beyi Enan oğlu Ahira sunusunu sundu:"],["79","Ağırlığı yüz otuz şekel olan bir gümüş tepsi, kutsal yerin şekeline göre yetmiş şekellik bir gümüş tas; bunların her ikisi de ekmek sunusu için yağla yoğrulmuş ince unla doluydu;"],["80","buhurla dolu, on şekellik bir altın kepçe;"],["81","yakmalık sunu için bir genç boğa, bir koç, bir yaşında bir erkek kuzu;"],["82","günah sunusu olarak bir teke;"],["83","esenlik kurbanı olarak iki sığır, beş koç, beş teke ve bir yaşında beş erkek kuzu. Bu, Enan oğlu Ahira'nın sunusuydu."],["84","Sunağın İsrael beyleri tarafından meshedildiği gün onun adama sunusu şunlardı: On iki gümüş tepsi, on iki gümüş tas, on iki altın kepçe;"],["85","her biri yüz otuz şekel ağırlığında gümüş tepsi ve her tas yetmiş şekel; kapların tüm gümüşü, kutsal yerin şekeline göre iki bin dört yüz şekeldi;"],["86","kutsal yerin şekeline göre her biri on şekel ağırlığında, buhurla dolu on iki altın kepçe; kepçelerdeki altınların tamamının ağırlığı yüz yirmi şekeldi;"],["87","yakmalık sunu için bütün sığırlar on iki boğa, on iki koç, bir yaşında on iki erkek kuzu ve bunların ekmek sunusu; ve günah sunusu olarak on iki teke;"],["88","ve esenlik sunuları kurbanı için bütün sığırlar: Yirmi dört boğa, altmış koç, altmış teke ve birer yaşında altmış erkek kuzu. Bu, sunağın meshedilmesinden sonra sunulan adama sunusuydu."],["89","Moşe, Yahve'yle konuşmak için Buluşma Çadırı'na girdiğinde, Levha Sandığı'nın üzerindeki Merhamet Örtüsü'nün üzerinden, iki keruvun arasından, kendisiyle konuşan O'nun sesini duydu; ve O'nunla konuştu."]],8:[["1","Yahve Moşe'ye şöyle konuştu:"],["2","“Aron'la konuş ve ona söyle: 'Kandilleri yaktığında, yedi kandil şamdanın önüne ışık verecek.'”"],["3","Aron öyle yaptı. Yahve'nin Moşe'ye buyurduğu gibi, şamdanın önündeki alanı aydınlatmak için kandillerini yaktı."],["4","Bu, şamdan işçiliğiydi, dövmeci işi altındı. Tabanından çiçeklerine kadar dövmeci işiydi. Şamdanı Yahve'nin Moşe'ye gösterdiği örneğe göre yaptı."],["5","Yahve Moşe'ye şöyle dedi:"],["6","“Levililer'i İsrael'in çocukları arasından alıp onları temizle."],["7","Onları temizlemek için şunu yapacaksın: Arınma suyunu üzerlerine serp, bütün vücutlarını usturayla tıraş etsinler, giysilerini yıkasınlar ve kendilerini temizlesinler."],["8","Sonra genç bir boğayla onun ekmek sunusunu, yağla yoğrulmuş ince unu alsınlar; ve günah sunusu olarak başka bir genç boğa alacaksın."],["9","Levililer'i Buluşma Çadırı'nın önüne çıkaracaksın. İsrael'in çocuklarının bütün topluluğunu bir araya toplayacaksın."],["10","Levililer'i Yahve'nin önüne çıkaracaksın. İsrael'in çocukları ellerini Levililer'in üzerine koyacaklar,"],["11","Aron, Yahve'ye hizmet etmek onların işi olsun diye, İsrael'in çocuklarının adına Levililer'i sallamalık sunu olarak Yahve'nin önünde sunacaktır.”"],["12","“Levililer ellerini boğaların başları üzerine koyacaklar; sen de Levililer'in günahlarını bağışlatmak için birini günah sunusu, diğerini de yakmalık sunu olarak Yahve'ye sunacaksın."],["13","Levililer'i Aron'la oğullarının önünde durduracaksın ve onları sallamalık sunu olarak Yahve'ye sunacaksın."],["14","Böylece Levililer'i İsrael'in çocuklarının arasından ayıracaksın ve Levililer benim olacaktır.”"],["15","“Bundan sonra Levililer Buluşma Çadırı'ndaki hizmete girecekler. Onları temizleyip sallamalık sunu olarak sunacaksın."],["16","Çünkü İsrael'in çocuklarının arasından onların tamamı bana verildi; rahmi açanların hepsinin yerine, bütün İsrael'in çocuklarının ilk doğanlarının yerine, onları kendime aldım."],["17","Çünkü İsrael'in çocuklarının arasında ilk doğanların tümü, insan olsun, hayvan olsun, benimdir. Mısır diyarında ilk doğanların hepsini vurduğum gün, onları kendim için kutsal kıldım."],["18","İsrael'in çocuklarının arasında ilk doğanların yerine Levililer'i aldım."],["19","İsrael'in çocukları kutsal yere yaklaştığı zaman İsrael'in çocukları arasında bela olmasın diye, Buluşma Çadırı'nda İsrael'in çocuklarına hizmet etmeleri ve İsrael'in çocuklarına kefaret etmeleri için İsrael'in çocukları arasından Levililer'i Aron'a ve oğullarına hediye olarak verdim.”"],["20","Moşe, Aron ve İsrael'in çocuklarının bütün topluluğu Levililer'e böyle yaptılar. Yahve'nin Levililer hakkında Moşe'ye buyurduğu her şeye göre İsrael'in çocukları da onlara öyle yaptılar."],["21","Levililer kendilerini günahtan arındırıp giysilerini yıkadılar; Aron, Yahve'nin önünde onları sallamalık sunu olarak sundu ve Aron onları temizlemek üzere onlar için kefaret etti."],["22","Bundan sonra Levililer, Aron'un ve oğullarının önünde hizmetlerini yapmak üzere Buluşma Çadırı'na girdiler; Yahve'nin Levililer hakkında Moşe'ye buyurduğu gibi onlara öyle yaptılar."],["23","Yahve Moşe'ye şöyle konuştu:"],["24","“Levililer'e verilen görev şudur: Yirmi beş yaş ve üstünde olanlar, Buluşma Çadırı hizmetinde hizmet etmek üzere içeri girecekler;"],["25","elli yaşını doldurduktan sonra hizmetten ayrılacaklar ve artık hizmet etmeyecekler."],["26","Ancak Buluşma Çadırı'ndaki kardeşlerinin görevi yerine getirmesine yardım edecekler ve hizmet etmeyecekler. Levililer'e görevlerini böyle yaptıracaksın.”"]],9:[["1","Mısır diyarından çıkışlarının ikinci yılının birinci ayında, Yahve Sina Çölü'nde Moşe'ye şöyle konuştu:"],["2","“İsrael'in çocukları Pesah'ı belirlenen zamanda tutsunlar."],["3","Bu ayın on dördüncü günü akşam, onu belirlenen zamanda tutacaksınız. Onu tüm kurallarına ve tüm ilkelerine göre tutacaksınız.”"],["4","Moşe İsrael'in çocuklarına Pesah'ı tutmaları gerektiğini söyledi."],["5","Birinci ayın on dördüncü günü akşam vakti Sina Çölü'nde Pesah'ı tuttular. Yahve'nin Moşe'ye buyurduğu her şeye göre İsrael'in çocukları öyle yaptı."],["6","İnsan ölüsü nedeniyle kirli sayılan, o gün Pesah'ı tutamayan bazı insanlar vardı ve o gün Moşe'yle Aron'un önüne geldiler."],["7","Bu kişiler ona, “İnsan ölüsü yüzünden kirliyiz” dediler. “Yahve'nin sunusunu belirlenen zamanda İsrael'in çocuklarının arasında sunmamamız için neden geri tutuluyoruz?”"],["8","Moşe onlara şu karşılığı verdi: “Durun da Yahve'nin sizin için ne buyuracağını duyayım.”"],["9","Yahve Moşe'ye şöyle konuştu:"],["10","“İsrael'in çocuklarına de ki: 'Sizden ya da soylarınızdan herhangi biri ölü yüzünden kirliyse, ya da uzak bir yolculuktaysa, yine de Yahve'ye Pesah tutacaktır."],["11","İkinci ayın on dördüncü günü akşam onu tutacaklar; onu mayasız ekmek ve acı otlarla yiyecekler."],["12","Sabaha kadar ondan bir şey bırakmayacaklar, bir kemiğini bile kırmayacaklar. Pesah kuralına göre onu tutacaklar."],["13","Ama temiz olup yolculukta olmayan ve Pesah'ı tutmayan insanın canı halkından atılacaktır. Belirlenen zamanda Yahve'ye sunu sunmadığı için bu adam günahını yüklenecektir.'”"],["14","“'Aranızda yaşayan bir yabancı Yahve'ye Pesah tutmak isterse, bunu Pesah kuralına ve ilkesine göre yapacaktır. Hem yabancı, hem de ülkede doğan kişi için tek bir kural olacak.'”"],["15","Konutun kurulduğu gün bulut, konutu, Levha Sandığı'nı örttü. Akşamleyin ateş görünüşü gibi sabaha kadar konutun üzerindeydi."],["16","Böylece hep devam etti. Bulut onu örterdi, geceleyin de ateş görünümü."],["17","Bulut Çadır'ın üzerinden kaldırılınca İsrael'in çocukları yola çıkardı; bulutun durduğu yerde de İsrael'in çocukları konaklardı."],["18","İsrael'in çocukları Yahve'nin buyruğuna göre yola çıkarlar ve Yahve'nin buyruğuna göre konaklarlardı. Bulut konutun üzerinde durduğu sürece konaklarlardı."],["19","Bulut konutun üzerinde çok günler kaldığı zaman İsrael'in çocukları Yahve'nin buyruğunu tutar ve yola çıkmazlardı."],["20","Bazen konutun üzerinde bulut birkaç gün kalırdı; o zaman Yahve'nin buyruğuna göre konaklar ve Yahve'nin buyruğuna göre yola çıkarlardı."],["21","Bazen bulut akşamdan sabaha kadar dururdu; ve sabahleyin bulut kaldırıldığında yola çıkarlardı; ya da gece gündüz bulut kaldırıldığında yolculuk yaparlardı."],["22","Bulut ister iki gün, ister bir ay, ister bir yıl olsun konutun üzerinde durduğunda, İsrael'in çocukları konaklar ve yola çıkmazlardı; ancak kaldırıldığında yola çıkarlardı."],["23","Yahve'nin buyruğuna göre konaklar ve Yahve'nin buyruğuna göre yola çıkarlardı. Yahve'nin Moşe aracılığıyla verdiği buyruk üzerine, Yahve'nin buyruğunu tutarlardı."]],10:[["1","Yahve Moşe'ye şöyle dedi:"],["2","“Gümüşten iki boru yap. Onları dövmeci işi olarak yapacaksın. Bunları topluluğu çağırmak ve orduların yola çıkması için kullanacaksın."],["3","Onlar çalınınca, bütün topluluk Buluşma Çadırı'nın kapısında senin yanında toplanacak."],["4","Biri bile çalınırsa, o zaman beyler, İsrael binlerinin başları senin yanında toplanacak."],["5","Yüksek sesle çaldığınızda doğu tarafında konaklayan ordular yola çıkacak."],["6","İkinci kez yüksek sesle çaldığınızda güney tarafında konaklayan ordular yola çıkacak. Yola çıkmaları için yüksek sesle çalacaklar."],["7","Topluluk toplanacağı zaman çalacaksınız, ancak yüksek sesle çalmayacaksınız.”"],["8","“Boruları Aron'un oğulları, kâhinler çalacaklar. Bu sizin için kuşaklar boyu daima geçerli bir kural olacaktır."],["9","Ülkenizde size baskı yapan düşmana karşı savaşa gittiğinizde, boruları yüksek sesle çalacaksınız. O zaman Tanrınız Yahve'nin önünde anılacak ve düşmanlarınızdan kurtulacaksınız.”"],["10","“Ayrıca sevinç günlerinde, bayramlarınızda ve aylarınızın başında, yakmalık sunularınızın ve esenlik sunularınızın üzerinde boruları çalacaksınız; ve onlar Tanrı'nın önünde sizin için anılma olacaklar. Ben Tanrınız Yahve'yim.”"],["11","İkinci yıl, ikinci ayın yirminci günü, bulut antlaşma konutunun üzerinden kaldırıldı."],["12","İsrael'in çocukları Sina Çölü'nden yolculuklarına devam ettiler; ve bulut Paran Çölü'nde durdu."],["13","Yahve'nin Moşe aracılığıyla verdiği buyruğa uyarak ilk defa yola çıktılar."],["14","Önce Yahuda çocukları ordugâhının bayrağı ordularına göre yola çıktı. Amminadav oğlu Nahşon onun ordusunun başındaydı."],["15","Suar oğlu Netanel, İssakar'ın çocukları oymağının ordusunun başındaydı."],["16","Helon oğlu Eliav, Zevulun'un çocukları oymağının ordusunun başındaydı."],["17","Konut indirildi; ve konutu taşıyan Gerşon'un oğulları ile Merari'nin oğulları yola çıktılar."],["18","Ruven ordugâhının bayrağı ordularına göre yola çıktı. Şedeur oğlu Elizur ordusunun başındaydı."],["19","Surişadday oğlu Şelumiel, Şimon'un çocukları oymağının ordusunun başındaydı."],["20","Deuel oğlu Elyasaf, Gad'ın çocukları oymağının ordusunun başındaydı."],["21","Kohatlılar kutsal yeri taşıyarak yola çıktılar. Diğerleri onlar gelmeden önce konutu kurarlardı."],["22","Efraim'in çocukları ordugâhının bayrağı ordularına göre yola çıktı. Ammihud oğlu Elişama onun ordusunun başındaydı."],["23","Pedahzur oğlu Gamaliel, Manaşşe'nin çocukları oymağının ordusunun başındaydı."],["24","Gideoni oğlu Avidan Benyamin'in çocukları oymağının ordusunun başındaydı."],["25","Bütün ordugâhların arka muhafızı olan Dan'ın çocukları ordugâhının bayrağı, ordularına göre yola çıktı. Ammişhadday oğlu Ahiezer onun ordusunun başındaydı."],["26","Okran oğlu Pagiel Aşer'in çocukları oymağının ordusunun başındaydı."],["27","Enan oğlu Ahira, Naftali'nin çocukları oymağının ordusunun başındaydı."],["28","Ordularına göre İsrael'in çocuklarının yola çıkışları böyleydi; ve onlar göç ettiler."],["29","Moşe, kayınpederi Midyanlı Reuel'in oğlu Hovav'a şöyle dedi: “Yahve'nin, 'Size vereceğim' dediği yere gidiyoruz. Bizimle gel, sana iyilik ederiz; çünkü Yahve İsrael hakkında iyilik konuştu.”"],["30","Ona, “Gitmeyeceğim” dedi. “Yalnız kendi topraklarıma ve akrabalarımın yanına gideceğim.”"],["31","Moşe, “Lütfen bizden ayrılma” dedi. “Çünkü çölde nasıl konaklayacağımızı sen biliyorsun ve bizim gözümüz olursun."],["32","Eğer bizimle gidersen, o zaman öyle olacak ki, Yahve bize ne iyilik yaparsa, biz de sana aynısını yapacağız.”"],["33","Yahve'nin Dağı'ndan üç günlük yol aldılar. Yahve'nin Antlaşma Sandığı, onlara dinlenme yeri bulmak için üç günlük yol boyunca önlerinden gidiyordu."],["34","Ordugâhtan yola çıkarken Yahve'nin bulutu gündüzün onların üzerindeydi."],["35","Sandık yola çıktığında Moşe şöyle dedi: “Kalk, ey Yahve, düşmanların dağılsın! Senden nefret edenler önünden kaçsın!”"],["36","Sandık durduğunda, “Ey Yahve, onbinlerce, binlerce İsraelli'ye dön” derdi."]],11:[["1","Halk Yahve'nin kulağına yakınıyordu. Yahve bunu duyunca öfkesi alevlendi; ve Yahve'nin ateşi onların arasında yandı ve ordugâhın bazı kenar kısımlarını kül etti."],["2","Halk Moşe'ye feryat etti; Moşe Yahve'ye dua etti ve ateş geçti."],["3","O yere Taberah adı verildi, çünkü onların arasında Yahve'nin ateşi yandı."],["4","Onların arasındaki karışık halk aşırı derecede iştahlandı; İsrael'in çocukları da yine ağlayıp dediler: “Bize yememiz için kim et verecek?”"],["5","Mısır'da bedava yediğimiz balığı hatırlıyoruz; salatalıkları, kavunları, pırasaları, soğanlar ve sarımsakları;"],["6","ama artık iştahımızı kaybettik. Bu mandan başka görülecek hiçbir şey yok.”"],["7","Kişniş tohumu gibi olan man, görünüşüyle de reçineye benziyordu."],["8","Halk dolaşır, onu toplardı, değirmende öğütür ya da havanda döverdi, tencerelerde kaynatır ve pideler yaparlardı. Tadı taze yağın tadı gibiydi."],["9","Gece ordugâhın üzerine çiy düştüğünde, üzerine man düşerdi."],["10","Moşe, herkesin çadırının kapısında, aile boyu ağladığını duydu; ve Yahve'nin öfkesi çok alevlendi; Moşe de hoşnutsuzdu."],["11","Moşe Yahve'ye şöyle dedi: “Hizmetkârına neden bu kadar kötü davrandın? Bütün bu halkın yükünü bana yüklediğin halde neden senin gözünde lütuf bulamadım?"],["12","Bu halkın tümüne ben mi gebe kaldım? Bana, 'Atalarına ant içtiğin ülkeye, emzikteki çocuğu taşıyan bir dadı gibi onları koynunda taşı' diyesin diye mi onları dışarı çıkardım?"],["13","Bunca insana verecek eti nereden bulabilirim? Çünkü, 'Bana et ver de yiyelim' diyerek önümde ağlıyorlar."],["14","Bu halkın tümünü ben tek başıma taşıyamam, çünkü bu benim için çok ağır."],["15","Eğer bana böyle davranırsan, eğer gözünde lütuf bulduysam, lütfen beni hemen öldür; ve sefaletimi görmeyeyim.”"],["16","Yahve Moşe'ye şöyle dedi: “Halkın ihtiyarları, onların ileri gelenleri olduğunu bildiğin İsrael ihtiyarlarından yetmiş kişiyi bana topla; ve onları Buluşma Çadırı'na getir ki, orada seninle dursunlar."],["17","İneceğim ve orada seninle konuşacağım. Senin üzerinde olan Ruh'tan alıp onların üzerine koyacağım; ve sen tek başına taşımayasın diye, halkın yükünü onlar seninle birlikte taşıyacaklar.”"],["18","“Halka de ki, 'Yarın için hazırlık yaparak kendinizi kutsal kılın, et yiyeceksiniz; çünkü siz, “Kim bize yemek için et verecek? Çünkü Mısır'da halimiz iyiydi.” diyerek Yahve'nin kulaklarına ağladınız. Bu nedenle Yahve size et verecek ve yiyeceksiniz."],["19","Sadece bir gün, iki gün, beş gün, on gün, yirmi gün değil,"],["20","ancak bütün bir ay; ta ki o, burnunuzdan gelinceye kadar; sizi tiksindirinceye kadar yiyeceksiniz; çünkü aranızda olan Yahve'yi reddettiniz ve “Mısır'dan neden çıktık?” diyerek O'nun önünde ağladınız.'”"],["21","Moşe şöyle dedi: “Aralarında bulunduğum halk yaya olarak altı yüz bin kişidir; ve sen, 'Bir ay boyunca yiyebilmeleri için onlara et vereceğim' dedin."],["22","Onlara yetecek kadar davar ve sığır onlar için boğazlanacak mı? Onlara yetecek kadar denizin bütün balıkları onlar için toplanacak mı?”"],["23","Yahve Moşe'ye şöyle dedi: “Yahve'nin eli mi kısaldı? Şimdi benim sözümün başınıza gelip gelmeyeceğini göreceksiniz.”"],["24","Moşe dışarı çıkıp halka Yahve'nin sözlerini anlattı; halkın ihtiyarlarından yetmiş kişiyi toplayıp Çadır'ın çevresinde durdurdu."],["25","Yahve bulutun içinde inip onunla konuştu ve kendisindeki Ruh'u alıp yetmiş ihtiyarın üzerine koydu. Ruh onların üzerinde durunca peygamberlik ettiler, ama bunu bir daha yapmadılar."],["26","Ancak ordugâhta iki kişi kaldı. Birinin adı Eldad, diğerinin adı Medad'dı; ve Ruh onların üzerine durdu. Onlar yazılanlar arasındaydı, ama Çadır'dan çıkmamış olanlardandı; ve ordugâhta peygamberlik ettiler."],["27","Genç bir adam koşup Moşe'ye şöyle dedi: “Eldad'la Medad ordugâhta peygamberlik ediyorlar!”"],["28","Moşe'nin seçmiş olduğu adamlardan biri olan hizmetkârı Nun oğlu Yeşu, “Efendim Moşe, onlara yasak koy!” diye yanıt verdi."],["29","Moşe ona şöyle dedi: “Sen benim için mi kıskanıyorsun? Keşke Yahve'nin tüm halkı peygamber olsaydı ve Yahve onların üzerine Ruhu'nu koysaydı!”"],["30","Moşe, kendisi ve İsrael'in ihtiyarları ordugâha girdiler."],["31","Yahve'den çıkan rüzgâr denizden bıldırcınları getirdi ve onları ordugâhın yakınına düşürdü; bu tarafta yaklaşık bir günlük yol, diğer tarafta ise ordugâhın çevresinde bir günlük yol olmak üzere yerin yüzeyinden iki arşın kadar yüksekteydi."],["32","Halk bütün o gün, bütün o gece ve bütün ertesi gün kalkıp bıldırcın topladı. En az toplayan on homer topladı ve kendileri için hepsini ordugâhın çevresine serdiler."],["33","Et henüz dişlerinin arasındayken, daha çiğnenmeden, Yahve'nin öfkesi halka karşı alevlendi ve Yahve halkı çok büyük bir belayla vurdu."],["34","İştahlanan halkı oraya gömdüklerinden o yere Kivrot Hattaava adı verildi."],["35","Halk Kivrot Hattaava'dan yola çıktı; ve Haserot'da kaldılar."]],12:[["1","Miryam ile Aron, evlendiği Kûşlu kadın yüzünden Moşe'ye karşı konuştular; çünkü Kûşlu bir kadınla evlenmişti."],["2","Onlar şöyle dediler: “Yahve gerçekten yalnızca Moşe'yle mi konuştu? Bizimle de konuşmadı mı?” Ve Yahve bunu duydu."],["3","Moşe denen adam, yeryüzündeki bütün insanlardan çok daha alçakgönüllüydü."],["4","Yahve ansızın Moşe'ye, Aron'a ve Miryam'a, “Siz üçünüz Buluşma Çadırı'na çıkın!” dedi. Üçü de dışarı çıktı."],["5","Yahve bir bulut sütunu içinde indi, Çadır'ın kapısında durup Aron'la Miryam'ı çağırdı; ve ikisi de öne çıktı."],["6","“Şimdi sözlerimi dinleyin” dedi. “Eğer aranızda bir peygamber varsa, ben Yahve, görümde ona kendimi tanıtacağım. Onunla rüyada konuşacağım."],["7","Hizmetkârım Moşe öyle değildir. O, tüm evimde sadıktır."],["8","Onunla bilmecelerle değil, ağızdan ağıza konuşacağım; ve Yahve'nin suretini görecek. O halde neden hizmetkârımın aleyhinde, Moşe aleyhinde konuşmaktan korkmadınız?”"],["9","Yahve'nin öfkesi onlara karşı alevlendi; ve oradan gitti."],["10","Bulut Çadırın üzerinden ayrıldı; ve işte, Miryam kar gibi beyaz, cüzamlıydı. Aron Miryam'a baktı ve onun cüzamlı olduğunu gördü."],["11","Aron Moşe'ye şöyle dedi: “Efendim, lütfen akılsızlık ederek işlediğimiz günahı, bu günahı bize sayma."],["12","Yalvarırım, o, annesinin rahminden çıktığında etinin yarısı tükenmiş bir ölü gibi olmasın.”"],["13","Moşe Yahve'ye şöyle feryat etti: “Tanrım, onu iyileştir, sana yalvarırım!”"],["14","Yahve Moşe'ye şöyle dedi: “Eğer babası onun yüzüne tükürseydi, yedi gün utanması gerekmez miydi? Yedi gün orduğâhın dışında kapalı kalsın, ondan sonra tekrar içeri getirilecek.”"],["15","Miryam yedi gün orduğâhın dışında kapatıldı ve Miryam tekrar getirilene kadar halk yola çıkmadı."],["16","Daha sonra halk Haserot'tan ayrıldı ve Paran Çölü'nde konakladı."]],13:[["1","Yahve Moşe'ye şöyle konuştu:"],["2","“İsrael'in çocuklarına vereceğim Kenan ülkesini araştırsınlar diye adamlar gönder. Atalarının her oymağından bir adam göndereceksin, her biri aralarında bir bey olacak.”"],["3","Moşe Yahve'nin buyruğu uyarınca onları Paran Çölü'nden gönderdi. Hepsi İsrael'in çocuklarının başları olan adamlardı."],["4","Adları şunlardı: Ruven oymağından Zakkur oğlu Şammua."],["5","Şimon oymağından Hori oğlu Şafat."],["6","Yahuda oymağından Yefunne oğlu Kalev."],["7","İssakar oymağından Yosef oğlu İgal."],["8","Efraim oymağından Nun oğlu Hoşea."],["9","Benyamin oymağından Rafu oğlu Palti."],["10","Zevulun oymağından Sodi oğlu Gaddiel."],["11","Yosef oymağından, Manaşşe oymağından Susi oğlu Gaddi."],["12","Dan oymağından Gemalli oğlu Ammiel."],["13","Aşer oymağından Mikael oğlu Setur."],["14","Naftali oymağından Vofsi oğlu Nahbi."],["15","Gad oymağından Maki oğlu Geuel."],["16","Moşe'nin ülkeyi araştırmak üzere gönderdiği adamların adları bunlardır. Moşe, Nun oğlu Hoşea'ya Yeşu adını verdi."],["17","Moşe onları Kenan ülkesini araştırmak üzere gönderip şöyle dedi: “Güneyden bu tarafa gidin ve dağlık bölgeye çıkın."],["18","Ülkenin nasıl olduğuna bakın; ve orada oturanlar, güçlü mü yoksa zayıf mı, az mı yoksa çok mu;"],["19","ve üzerinde oturdukları yer nasıl, iyi mi yoksa kötü mü, içinde oturdukları kentler nasıl, açık mı yoksa surlu mu;"],["20","ve toprağın nasıl, verimli mi yoksa zayıf mı, içinde ağaç var mı yoksa yok mu? Cesur olun ve memleketin ürününden biraz getirin.” Şimdi vakit üzüm turfandası zamanıydı."],["21","Böylece çıkıp Zin Çölü'nden Rehov'a, Hamat'ın girişine kadar olan ülkeyi araştırdılar."],["22","Güney yönünde ilerleyerek Hevron'a geldiler; Anak'ın çocukları Ahiman, Şeşay ve Talmay da oradaydı. (Hevron, Mısır'daki Soan'dan yedi yıl önce kurulmuştu.)"],["23","Eşkol Vadisi'ne geldiler ve oradan bir salkım üzüm ile birlikte bir dal kestiler ve onu iki adam sırıkta taşıdı. Biraz narlardan ve incirlerden de getirdiler."],["24","İsrael'in çocuklarının oradan kestiği salkımlardan dolayı oraya Eşkol Vadisi denildi."],["25","Kırk gün sonra ülkeyi araştırmaktan döndüler."],["26","Paran Çölü'ne, Kadeş'e gidip Moşe'nin, Aron'un ve İsrael'in çocuklarının bütün topluluğunun yanına geldiler; ve onlara ve tüm topluluğa haber getirdiler. Onlara memleketin ürününü gösterdiler."],["27","Bunu ona bildirip dediler: “Bizi gönderdiğin ülkeye vardık. Gerçekten süt ve bal akıyor ve bu da onun ürünüdür."],["28","Ancak ülkede oturan halk güçlü, kentler surlu ve çok büyük. Üstelik Anak'ın çocuklarını da orada gördük."],["29","Amalek Güney ülkesinde oturuyor. Hititler, Yebuslular ve Amorlular dağlık bölgede oturuyorlar. Kenanlılar deniz kıyısında ve Yarden kıyısı boyunca oturuyorlar.”"],["30","Kalev Moşe'nin önünde halkı susturdu ve şöyle dedi: “Hemen çıkıp orayı ele geçirelim; çünkü biz bunun üstesinden gelebiliriz!”"],["31","Ama onunla birlikte çıkan adamlar şöyle dediler: “O halka karşı çıkmaya gücümüz yetmez; çünkü onlar bizden daha güçlüdürler.”"],["32","Araştırdıkları ülke hakkında İsrael'in çocuklarına kötü haber getirdiler ve şöyle dediler: “Araştırmak için içinden geçtiğimiz ülke, içinde oturanları yiyip bitiren bir ülkedir; ve orada gördüğümüz insanların hepsi uzun boylu insanlardı."],["33","Orada Nefilim'den gelen Anak'ın oğullarını Nefilim'i gördük. Kendi gözümüzde çekirgeler gibiydik ve onların gözünde de öyleydik.”"]],14:[["1","Bütün topluluk sesini yükseltip bağırdı; ve insanlar o gece ağladılar."],["2","Bütün İsrael'in çocukları Moşe'ye ve Aron'a karşı söylendiler. Bütün topluluk onlara şöyle dedi: “Keşke Mısır diyarında ölseydik, ya da bu çölde ölseydik!"],["3","Yahve bizi neden bu ülkeye kılıçla düşelim diye götürüyor? Karılarımız ve çocuklarımız ya yakalanacak, ya da öldürülecek! Mısır’a dönmemiz daha iyi olmaz mı?”"],["4","Birbirlerine, “Bir önder seçip Mısır'a dönelim” dediler."],["5","Bunun üzerine Moşe ile Aron, İsrael'in çocukları topluluğunun bütün meclisi önünde yüzüstü yere kapandılar."],["6","Ülkeyi araştıranlardan Nun oğlu Yeşu ile Yefunne oğlu Kalev giysilerini yırttılar."],["7","İsrael'in çocuklarının bütün topluluğuna şöyle dediler: “Araştırmak için içinden geçtiğimiz ülke son derece iyi bir ülkedir."],["8","Eğer Yahve bizden hoşnutsa, bizi bu ülkeye, süt ve bal akan ülkeye getirecek ve onu bize verecektir."],["9","Yalnız Yahve'ye isyan etmeyin, ülke halkından da korkmayın; çünkü onlar bizim için ekmektir. Savunmaları onların üzerinden kaldırıldı ve Yahve bizimledir. Onlardan korkmayın.”"],["10","Ama bütün topluluk onları taşlamakla tehdit etti. Yahve'nin görkemi Buluşma Çadırı'nda bütün İsrael'in çocuklarına göründü."],["11","Yahve Moşe'ye şöyle dedi: “Bu halk beni ne zamana dek küçümseyecek? Aralarında yapmış olduğum tüm belirtilere rağmen ne zamana dek bana inanmayacaklar?"],["12","Onları vebayla vuracağım, onları mirastan mahrum bırakacağım ve seni onlardan daha büyük ve daha güçlü bir ulus yapacağım.”"],["13","Moşe Yahve'ye şöyle dedi: “O zaman Mısırlılar bunu duyacak; çünkü bu halkı kendi gücünle onların arasından çıkardın."],["14","Bunu bu ülkede oturanlara anlatacaklar. Sen, Yahve'nin bu halkın arasında olduğunu duydular; çünkü sen, Yahve yüz yüze görünüyorsun ve senin bulutun onların üzerinde duruyor; sen gündüz bulut sütunu içinde, gece ateş sütunu içinde onların önünde yürüyorsun."],["15","Eğer bu halkı bir adam gibi öldürürsen, o zaman ününü duyan uluslar şöyle diyecekler,"],["16","'Çünkü Yahve bu halkı kendilerine ant içerek söz verdiği ülkeye götüremediği için onları çölde katletti.'"],["17","Şimdi, söyleyip dediğin gibi, lütfen Efendi'nin gücü büyük olsun,"],["18","'Yahve öfkelenmekte yavaştır, sevgi dolu iyiliği boldur, haksızlığı ve itaatsizliği bağışlar; suçluyu asla temize çıkarmaz, babaların suçu için çocukların, üçüncü ve dördüncü kuşaklarını ziyaret eder.'"],["19","Mısır'dan bugüne kadar bu halkı bağışladığın gibi, sevginin büyüklüğüne göre, lütfen, bu halkın suçunu bağışla.”"],["20","Yahve şöyle dedi: “Senin sözün uyarınca bağışladım;"],["21","ancak gerçekte, varlığımın hakkı için, tüm dünya Yahve'nin görkemi ile dolacaktır,"],["22","çünkü yüceliğimi ve Mısır'da, çölde yaptığım harikalarımı gören bütün bu adamlar, yine de beni on kez denediler, benim sözümü de dinlemediler;"],["23","atalarına ant içtiğim ülkeyi kesin olarak görmeyecekler, beni küçümseyenlerden hiçbiri orayı görmeyecektir."],["24","Ama hizmetkârım Kalev'i, kendisinde başka bir ruh olduğu ve tümüyle peşimden geldiği için gitmiş olduğu ülkeye onu götüreceğim. Onun soyu onu mülk edinecektir."],["25","Amalekliler ile Kenanlılar vadide oturduğu için, yarın dönüp Kızıldeniz yolundan çöle gidin.”"],["26","Yahve Moşe ve Aron'la konuşup şöyle dedi:"],["27","“Bana karşı söylenen bu kötü topluluğa daha ne kadar katlanacağım? İsrael'in çocuklarının bana karşı olan söylenmelerini duydum."],["28","Onlara de ki, 'Varlığım hakkı için diyor Yahve, kulaklarıma söylediğiniz gibi, kesinlikle size de öyle yapacağım."],["29","Cesetleriniz bu çöle serilecek; bana karşı söylenen yirmi yaş ve üzeri, tam sayınıza göre sizden tüm sayılanlar,"],["30","sizi orada oturtacağıma ant içtiğim ülkenin içine, Kalev, Yefunne oğlu ve Nun oğlu Yeşu dışında siz kesin olarak girmeyeceksiniz."],["31","Ama yakalanacaklarını ya da öldürüleceklerini söylediğiniz çocuklarınızı oraya götüreceğim ve sizin reddettiğiniz ülkeyi onlar bilecekler."],["32","Ama size gelince, cesetleriniz bu çöle serilecek."],["33","Çocuklarınız kırk yıl çölde dolaşacak ve cesetleriniz çölde tükeninceye kadar sizin fahişeliğinize katlanacaklar."],["34","Ülkeyi araştırdığınız günlerin sayısı kadar, kırk gün, her gün için bir yıl, kırk yıl boyunca suçlarınıza katlanacaksınız ve size yabancı olduğumu bileceksiniz.'"],["35","Ben, Yahve, söyledim. Bunu bana karşı toplanan bütün bu kötü topluluğa mutlaka yapacağım. Bu çölde yok olup gidecekler ve orada ölecekler.”"],["36","Moşe'nin ülkeyi araştırmak için gönderdiği adamlar geri döndüler ve ülke hakkında kötü haberler çıkararak tüm topluluğu ona karşı söylendiren adamlar,"],["37","ülkeyle ilgili kötü haberler getiren o adamlar Yahve'nin önünde vebadan öldüler."],["38","Ülkeyi araştırmak için giden adamlardan Nun oğlu Yeşu ile Yefunne oğlu Kalev sağ kaldılar."],["39","Moşe bu sözleri bütün İsrael'in çocuklarına söyledi ve halk büyük yas tuttu."],["40","Sabah erkenden kalkıp dağın tepesine çıkıp şöyle dediler: “İşte, biz buradayız ve Yahve'nin söz verdiği yere çıkacağız; çünkü günah işledik.”"],["41","Moşe şöyle dedi: “Başarılı olunmayacak şey için neden şimdi Yahve'nin buyruğuna karşı geliyorsunuz?"],["42","Çıkmayın, çünkü Yahve aranızda değildir; bu şekilde düşmanlarınızın önünde vurulmayasınız."],["43","Çünkü orada Amalekliler ve Kenanlılar önünüzdedir; Yahve'nin ardınca gitmekten döndüğünüz için kılıçtan geçirileceksiniz; bu nedenle Yahve sizinle olmayacaktır.”"],["44","Ama onlar dağın tepesine çıkmakla hadlerini aştılar. Buna rağmen Yahve'nin Antlaşma Sandığı ve Moşe ordugâhtan ayrılmadı."],["45","Bunun üzerine Amalekliler ve o dağda oturan Kenanlılar indiler ve onları vurup Horma'ya kadar kırdılar."]],15:[["1","Yahve Moşe'ye şöyle konuştu:"],["2","“İsrael'in çocuklarına söyle ve onlara de ki: 'Size vermekte olduğum, oturacağınız diyara girdiğinizde,"],["3","Yahve'ye ateşle yapılan sunu—yakmalık sunu olsun, ya da kurban olsun, ya da adak yerine getirme olsun, ya da gönülden verilen bir sunu olsun, ya da belli bayramlarınızda Yahve'ye hoş koku yapmak için sığırdan ya da davardan kurban olsun—"],["4","o zaman sunusunu sunan kişi, Yahve’ye ekmek sunusu olarak dörtte bir hin yağla yoğrulmuş onda bir efa ince un sunacaktır."],["5","Dökmelik sunu olarak, yakmalık sunu ya da kurbanla birlikte her kuzu için dörtte bir hin şarap hazırlayacaksın.'”"],["6","“'Koç için, ekmek sunusu için bir hinin üçte biri yağla yoğrulmuş onda iki efa ince un hazırlayacaksın;"],["7","ve dökmelik sunu olarak Yahve'ye hoş kokulu bir hin üçte bir oranında şarap sunacaksın."],["8","Yakmalık sunu, kurban, adak yerine getirme, ya da esenlik sunuları için Yahve'ye boğa hazırladığında,"],["9","boğayla birlikte ekmek sunusu olarak yarım hin yağla yoğrulmuş efanın onda üçü ince un sunacaktır;"],["10","ve dökme sunusu olarak, ateşle yapılan sunu, Yahve'ye hoş koku olarak yarım hin şarap sunacaksın."],["11","Her boğa, her koç, her erkek kuzu ya da oğlak için böyle yapılacaktır."],["12","Hazırlayacağınız sayıya göre, herkesin sayısına göre öyle yapacaksınız.'”"],["13","“'Memlekette doğan herkes bunları Yahve'ye ateşle yapılan, hoş kokulu bir sunu olarak bu şekilde yapacak."],["14","Eğer bir yabancı sizinle birlikte garip olarak yaşıyorsa, ya da kuşaklarınız boyunca aranızda olan ve Yahve'ye ateşle yapılan, hoş kokulu bir sunu sunarsa, sizin yaptığınız gibi, öyle yapacaktır."],["15","Topluluk için, hem sizin için, hem de yabancı olarak yaşayan garip için, kuşaklarınız boyunca daima geçerli tek bir kural olacak. Siz nasılsanız, yabancı da Yahve'nin önünde öyle olacaktır."],["16","Sizin için de, sizinle yabancı olarak yaşayan garip için de, bir yasa ve bir ilke olacaktır.'”"],["17","Yahve Moşe'ye şöyle konuştu:"],["18","“İsrael'in çocuklarına söyle ve onlara şunu de: 'Sizi götürmekte olduğum ülkeye girdiğinizde,"],["19","böyle olacak, o ülkenin ekmeğinden yediğinizde, Yahve'ye sallamalık sunu sunacaksınız."],["20","İlk hamurunuzdan sallamalık sunu olarak bir pide sunacaksınız. Onu harman sallama sunusu olarak kaldıracaksınız."],["21","Kuşaklarınız boyunca Yahve'ye ilk hamurunuzdan sallamalık sunu sunacaksınız.'”"],["22","“'Yanlış yaptığınızda ve Yahve'nin Moşe'ye söylediği tüm bu buyrukları,"],["23","Yahve'nin buyurduğu günden itibaren kuşaklarınız boyunca tutmadığınızda,"],["24","o zaman böyle olacak; eğer bu, topluluk tarafından bilmeden yapılmışsa, tüm topluluk, yakmalık sunu, Yahve'ye hoş koku olarak genç bir boğa, usule göre onun ekmek sunusuyla dökmelik sunusunu, suç sunusu olarak bir teke sunacaktır."],["25","Kâhin İsrael'in çocuklarının bütün topluluğu için kefaret edecektir ve onlar bağışlanacaktır; çünkü bu bir hataydı ve hatalarından dolayı sunularını, Yahve'ye ateşle yapılan sunuyu ve onların günah sunusunu Yahve'nin önüne getirmişlerdir."],["26","İsrael'in çocuklarının bütün topluluğu ve aralarında garip olarak yaşayan yabancı da bağışlanacaktır; çünkü bu tüm insanlarla ilgilidir, farkında olmadan yapıldı.'”"],["27","“'Bir kimse bilmeden günah işlerse, o zaman günah sunusu olarak bir yaşında bir dişi keçi sunacaktır."],["28","Yahve'nin önünde bilmeden günah işleyen can için kâhin kefaret edecek. Onun için kefaret edecek; o da bağışlanacaktır."],["29","İsrael'in çocukları arasında yerli olsun, aralarında oturan yabancı olsun, bilmeden yanlış bir şey yapan için, tek bir yasanız olacaktır.'”"],["30","“'Ama ister yerli, ister yabancı olsun, herhangi bir şeyi bilinçli yapan can, Yahve'ye küfretmiştir. O can halkının arasından atılacaktır."],["31","Yahve'nin sözünü küçümsediği ve buyruğu çiğnediği için o can mutlaka atılacaktır. Kötülüğü kendi üzerinde olacaktır.'”"],["32","İsrael'in çocukları çöldeyken Şabat Günü odun toplayan bir adam buldular."],["33","Onu odun toplarken bulanlar onu Moşe'yle Aron'un ve bütün topluluğun yanına getirdiler."],["34","Ona ne yapılacağı bildirilmediği için onu gözaltına aldılar."],["35","Yahve Moşe'ye şöyle dedi: “O adam kesinlikle öldürülecektir. Bütün topluluk ordugâhın dışında onu taşlayacaktır.”"],["36","Yahve'nin Moşe'ye buyurduğu gibi, bütün topluluk onu ordugâhın dışına çıkardı ve onu taşlarla taşlayarak öldürdü."],["37","Yahve Moşe'ye şöyle konuştu,"],["38","“İsrael'in çocuklarına söyle ve onlara kuşaklar boyunca giysilerinin kenarlarına saçak yapmalarını ve her eteğin saçağı üzerine mavi kordon koymalarını söyle."],["39","Görebilmeniz ve Yahve'nin bütün buyruklarını hatırlayıp onları yapmanız için bu size bir saçak olacak; ta ki, ardınca fahişelik etmiş olduğunuz kendi yüreğinizin ve kendi gözlerinizin ardınca gitmeyesiniz;"],["40","öyle ki, bütün buyruklarımı hatırlayıp yapasınız ve Tanrınız'a kutsal olasınız."],["41","Tanrınız olmak için sizi Mısır diyarından çıkaran Tanrınız Yahve benim; Ben Tanrınız Yahve'yim.”"]],16:[["1","Levi oğlu Kohat oğlu Yishar oğlu Korah, Ruven'in oğullarından Eliav'ın oğulları Datan ve Aviram ve Pelet oğlu On ile birlikte birkaç adam aldı."],["2","İsrael'in çocuklarından bazılarıyla birlikte, topluluğun iki yüz elli beyi, meclise çağrılanlar, tanınmış kişiler Moşe'nin önünde kalktılar."],["3","Moşe ve Aron'a karşı bir araya gelerek şöyle dediler: “Kendinize gereğinden fazla pay çıkarıyorsunuz; çünkü bütün topluluk, onlardan her biri kutsaldır, Yahve de onların arasındadır. Neden kendinizi Yahve'nin topluluğu üstüne çıkarıyorsunuz?”"],["4","Moşe bunu duyunca yüzüstü kapandı."],["5","Korah'la yanındakilere şöyle dedi: “Sabahleyin Yahve kendisinin olanı, kutsal olanı gösterecek ve onu kendisine yaklaştıracaktır. Seçeceği kişiyi kendisine yaklaştıracaktır."],["6","Şunu yapın: Ey Korah ve yanındakiler kendinize buhurdanlar alın,"],["7","içlerine ateş koyun ve yarın Yahve'nin önünde üzerlerine buhur koyun. Yahve'nin seçeceği kişi kutsal olacaktır. Siz çok ileri gittiniz, Levioğulları!”"],["8","Moşe Korah'a şöyle dedi: “Şimdi dinleyin, ey Levioğulları!"],["9","Sizi kendisine yakınlaştırmak, Yahve'nin konutunda hizmet etmek ve topluluğun önünde durup onlara hizmet etmek için İsrael'in Tanrısı'nın sizi İsrael topluluğundan ayırması size az mı geldi?"],["10","Seni ve Levioğulları kardeşlerinin tümünü seninle birlikte kendisine yaklaştırmadı mı? Kâhinliği de mi arıyorsunuz?"],["11","Bu nedenle sen ve bütün yanındakiler Yahve'ye karşı bir araya geldiniz! Aron nedir ki, ona karşı söyleniyorsunuz?”"],["12","Moşe Eliav'ın oğulları Datan ve Aviram'ı çağırmak için adam gönderdi; onlar da, “Çıkmayacağız!” dediler."],["13","Bizi süt ve bal akan bir diyardan çıkarıp çölde öldürmek için çıkarman azmış gibi, üzerimize bey de mi olacaksın?"],["14","Bizi süt ve bal akan bir diyara da getirmedin, miras olarak tarlalar ve bağlar da vermedin. Bu adamların gözlerini mi çıkaracaksın? Çıkmayacağız.”"],["15","Moşe çok kızmıştı ve Yahve'ye şöyle dedi: “Onların sunularına değer verme. Onlardan bir eşek bile almadım, hiçbirini de incitmedim.”"],["16","Moşe Korah'a şöyle dedi: “Sen ve bütün arkadaşların, sen, onlar ve Aron, yarın Yahve'nin önüne çıkın."],["17","Her biriniz kendi buhurdanını alıp üzerine buhur koysun. Her biriniz kendi buhurdanını, iki yüz elli buhurdanını Yahve'nin önüne getirsin; sen ve Aron da, ikiniz de kendi buhurdanınızı getirin.”"],["18","Her biri kendi buhurdanını alıp içine ateş koydu, üzerine buhur koydu ve Moşe ve Aron'la birlikte Buluşma Çadırı'nın kapısında durdu."],["19","Korah bütün topluluğu onlara karşı, Buluşma Çadırı'nın kapısında topladı. Yahve'nin görkemi bütün topluluğa göründü."],["20","Yahve Moşe ve Aron'a şöyle konuştu:"],["21","“Bu topluluğun arasından ayrılın da onları bir anda tüketeyim!”"],["22","Yüzüstü yere kapanıp şöyle dediler: “Tanrı, tüm insan ruhlarının Tanrısı, bir kişi günah işleyince bütün topluluğa mı kızacaksın?”"],["23","Yahve Moşe'ye şöyle konuştu:"],["24","“Topluluğa söyle ve, 'Korah, Datan ve Aviram'ın çadırının çevresinden uzaklaş' de.”"],["25","Moşe kalkıp Datan ve Aviram'ın yanına gitti; İsrael'in ihtiyarları da onun ardından gittiler."],["26","Topluluğa şöyle dedi: “Lütfen bu kötü adamların çadırlarından ayrılın ve onların hiçbir şeyine dokunmayın, yoksa onların bütün günahlarıyla tükenirsiniz!”"],["27","Böylece onlar Korah'ın, Datan'ın ve Aviram'ın çadırının her yanından uzaklaştılar. Datan ile Aviram dışarı çıkıp karıları, oğulları ve küçük çocuklarıyla birlikte çadırlarının kapısında durdular."],["28","Moşe şöyle dedi: “Bütün bu işleri yapmam için Yahve'nin beni gönderdiğini bununla bileceksiniz; çünkü bunlar benim kendi fikrim değildir."],["29","Eğer bu adamlar herkesin öldüğü gibi ölürse, ya da herkesin yaşadığını yaşarsa, o zaman Yahve beni göndermemiştir."],["30","Ama eğer Yahve yeni bir şey yaparsa ve yer ağzını açarsa, onları ve kendilerine ait olan her şeyi yutarsa ve onlar da diri diri Şeol'e inerlerse, o zaman bu adamların Yahve'yi küçümsediklerini anlayacaksınız.”"],["31","Tüm bu sözleri söylemeyi bitirince, onların altındaki yer yarıldı."],["32","Yer ağzını açtı ve onları, ev halklarını, Korah'ın bütün adamlarını ve mallarını yuttu."],["33","Böylece onlar ve onlara ait olanların hepsi diri diri Şeol'e indiler. Yer onların üzerine kapandı ve topluluğun arasından yok oldular."],["34","Etraflarında bulunan İsrael'in tümü onların feryadı üzerine kaçtı; çünkü, “Yer bizi yutmasın!” dediler."],["35","Yahve'nin yanından gelen ateş buhur sunan iki yüz elli kişiyi yiyip bitirdi."],["36","Yahve Moşe'ye şöyle konuştu:"],["37","“Kâhin Aron oğlu Eleazar'a söyle, o da yangından buhurdanları alıp ordugâhın dışına dağıtsın; çünkü onlar kutsaldır,"],["38","kendi hayatlarına karşı günah işleyenlerin buhurdanlarıdır. Onları sunak için örtü olmak üzere dövülmüş levhalar yapsınlar, çünkü onları Yahve'nin önünde sundular. Bu nedenle kutsaldırlar. Bunlar İsrael'in çocuklarına bir belirti olacaktır.”"],["39","Kâhin Eleazar, yakılan adamların sunduğu tunç buhurdanları aldı;"],["40","Aron'un soyundan olmayan hiçbir yabancı Yahve'nin önünde buhur yakmak üzere yaklaşmasın ve Korah ve onun arkadaşları gibi olmasın diye, İsrael'in çocuklarına anılma olmak üzere, Yahve'nin Moşe aracılığıyla kendisine söylemiş olduğu gibi sunak için örtü olarak buhurdanları dövdüler."],["41","Ama ertesi gün İsrael'in çocukları topluluğunun tümü Moşe'ye ve Aron'a karşı söylenip, “Yahve'nin halkını siz öldürdünüz!” dediler."],["42","Topluluk Moşe'ye ve Aron'a karşı toplandığında, Buluşma Çadırı'na doğru baktılar. İşte, bulut onu örttü ve Yahve'nin görkemi ortaya çıktı."],["43","Moşe'yle Aron Buluşma Çadırı'nın önüne geldiler."],["44","Yahve Moşe'ye şöyle dedi:"],["45","“Bu topluluğun arasından çıkın da onları bir anda tüketeyim!” Yüzüstü kapandılar."],["46","Moşe Aron'a şöyle dedi: “Buhurdanını al, sunaktan üzerine ateş koy, üzerine buhur koy, onu hemen topluluğa taşı ve onlar için kefaret et; çünkü Yahve'nin yanından gazap çıktı! Veba başladı.”"],["47","Aron Moşe'nin dediğini yaptı ve topluluğun ortasına koştu. Halk arasında veba çoktan başlamıştı. Buhur yakıp halk için kefaret etti."],["48","Ölülerle diriler arasında durdu; veba da durdu."],["49","Korah meselesi yüzünden ölenlerin yanı sıra vebadan ölenlerin sayısı da on dört bin yedi yüz kişiydi."],["50","Aron Moşe'nin yanına, Buluşma Çadırı'nın kapısına döndü ve salgın kesildi."]],17:[["1","Yahve Moşe'ye şöyle konuştu:"],["2","“İsrael'in çocuklarına söyle ve onlardan her ata evi için bir tane olmak üzere, atalarının evlerine göre bütün beylerinden on iki değnek al. Her birinin adını değneğinin üzerine yaz."],["3","Aron'un adını Levi değneği üzerine yazacaksın. Atalarının evlerinin her beyi için bir değnek olacak."],["4","Onları Buluşma Çadırı'nda sizinle buluştuğum Levha'nın önüne koyacaksınız."],["5","Seçeceğim adamın değneği tomurcuklanacak. İsrael'in çocuklarının size karşı söylenmelerini benden kaldıracağım.”"],["6","Moşe İsrael'in çocuklarıyla konuştu; ve onların bütün beyleri ona, atalarının evlerine göre her bey için bir tane olmak üzere toplam on iki değnek verdiler. Aron'un değneği de onların değnekleri arasındaydı."],["7","Moşe değnekleri Tanıklık Çadırı'nda Yahve'nin önüne koydu."],["8","Ertesi gün Moşe Tanıklık Çadırı'na girdi; ve işte, Aron'un Levi evi için olan değneği filizlenmiş, tomurcuklanmış, çiçek açmış ve olgun bademler vermişti."],["9","Moşe bütün değnekleri Yahve'nin önünden bütün İsrael'in çocuklarına çıkardı. Baktılar ve her biri kendi değneğini aldı."],["10","Yahve Moşe'ye şöyle dedi: “İsyan çocuklarına karşı bir işaret olarak saklanmak üzere Aron'un değneğini yine Levha'nın önüne koy; ta ki, bana karşı söylenmelerine bir son ver ki, ölmesinler.”"],["11","Moşe öyle yaptı. Yahve ona nasıl buyurduysa öyle yaptı."],["12","İsrael'in çocukları Moşe'ye şöyle dediler: “İşte, yok oluyoruz! İşimiz bitti! Hepimizin işi bitti!"],["13","Yahve'nin konutuna yaklaşan herkes ölüyor! Hepimiz yok mu olacağız?”"]],18:[["1","Yahve Aron'a şöyle dedi: “Kutsal yerin kötülüğünü sen ve seninle birlikte, oğulların ve atalarının evi taşıyacaksınız; sen ve seninle birlikte oğulların kâhinliğinizin suçunu taşıyacaksınız."],["2","Kardeşlerinizi, atanızın oymağını, Levi oymağını da yanınıza getirin ki, onlar da size katılsınlar ve size hizmet etsinler; ama sen ve oğulların Levha Çadırı'nın önünde olacaksınız."],["3","Buyruklarınızı ve tüm Çadır'ın görevini tutacaklar; ancak ne onlar ne de siz ölmeyesiniz diye kutsal yerdeki takımlara ve sunağa yaklaşmayacaklar."],["4","Onlar size katılacak ve Buluşma Çadır'ın tüm hizmetinin sorumluluğunu, tüm Çadır hizmeti için tutacaklar. Bir yabancı size yaklaşmayacak.”"],["5","“İsrael'in çocukları üzerinde artık gazap olmasın diye, konutun görevini ve sunağın görevini siz yerine getireceksiniz."],["6","İşte, ben kendim İsrael'in çocukları arasından kardeşleriniz Levililer'i aldım. Bunlar, Buluşma Çadırı'nın hizmetini yapmak için Yahve'ye adanmış olarak size verilen bir armağandır."],["7","Sen ve seninle birlikte olan oğulların, sunağın her şeyi ve perdenin iç tarafı için kâhinliğinizi tutacaksınız. Hizmet edeceksiniz. Size kâhinlik hizmetini bir armağan olarak veriyorum. Yaklaşan yabancı öldürülecektir.”"],["8","Yahve Aron'a şöyle konuştu: “İşte, sallamalık sunularımı, İsrael'in çocuklarına ait bütün kutsal şeyleri ben kendim sana verdim. Bunları mesh nedeniyle sana ve oğullarına sonsuza dek pay olarak verdim."],["9","Ateşten gelen çok kutsal şeylerden biri bu olacak: Onların bana sunacakları her sunu, onların her ekmek sunusu, onların her günah sunusu ve onların her suç sunusu senin ve oğulların için çok kutsal olacaktır."],["10","Onları çok kutsal şeyler gibi yiyeceksiniz. Her erkek ondan yiyecek. Senin için kutsal olacaktır.”"],["11","“Bu da senindir: Onların armağanının sallamalık sunuları, İsrael'in çocuklarının sallamalık sunularının tümü. Bunları sana, seninle birlikte oğullarına ve kızlarına sonsuza dek pay olarak verdim. Evinizde temiz olan herkes ondan yiyecektir.”"],["12","“Yahve'ye verdikleri yağın en iyisini, bağ bozumunun en iyisini, tahılın ve bunların ilk ürünlerini sana verdim."],["13","Memleketlerinde olanın tümünden Yahve'ye getirdikleri ilk olgun meyveler senin olacak. Evinizde temiz olan herkes ondan yiyecektir.”"],["14","“İsrael'de adanan her şey senin olacaktır."],["15","İnsan olsun hayvan olsun Yahve'ye sundukları her canlıdan rahmi açan her şey sizin olacak. Bununla birlikte, mutlaka insanın ilk doğanı ile kirli hayvanların ilk doğanlarının bedelini alacaksın."],["16","Senin biçtiğin değere göre bedel alınacak olanlardan, bir aylıktan itibaren, yirmi gerah ağırlığındaki kutsal yerin şekeline göre beş şekel para olarak, bedel alacaksın."],["17","Ancak ineğin ilk doğanı, koyunun ilk doğanı ya da keçinin ilk doğanı için bedel almayacaksın. Onlar kutsaldır. Kanlarını sunağın üzerine serpeceksin, ve yağlarını, Yahve'ye hoş koku olması için ateşle yapılan sunu olarak yakacaksın."],["18","Onların eti senin olacak, sallamalık sunu döş ve sağ but gibi senin olacaklar."],["19","İsrael'in çocuklarının Yahve'ye sunduğu kutsal şeylerden sallamalık sunuların hepsini sonsuza dek pay olarak sana, oğullarına ve kızlarına verdim. Bu, Yahve'nin önünde seninle ve seninle birlikte soyuna daima geçerli bir tuz antlaşmasıdır.”"],["20","Yahve Aron'a şöyle dedi: “Onların diyarında senin mirasın olmayacak, aralarında hiçbir payın olmayacak. İsrael'in çocukları arasında senin payın ve mirasın benim.”"],["21","“İşte, yaptıkları hizmete, Buluşma Çadırı hizmetine karşılık, İsrael'deki tüm ondalığı miras olarak Levi çocuklarına verdim."],["22","Bundan böyle İsrael'in çocukları, günah yüklenip ölmesinler diye Buluşma Çadırı'na yaklaşmayacaklar."],["23","Ancak Buluşma Çadırı'nın hizmetini Levililer yapacak ve onların suçunu onlar yüklenecek. Kuşaklarınız boyunca daima geçerli bir kural olacak. İsrael'in çocukları arasında onların mirası olmayacaktır."],["24","Çünkü İsrael'in çocuklarının Yahve'ye sallamalık sunu olarak sundukları ondalığı miras olarak Levililer'e verdim. Bu nedenle onlara, 'İsrael'in çocukları arasında mirasları olmayacak' dedim.”"],["25","Yahve Moşe'ye şöyle konuştu:"],["26","“Ayrıca Levililer'le konuşup onlara şöyle diyeceksin: 'İsrael'in çocuklarından mirasınız olarak size verdiğim ondalığı aldığınız zaman, ondan Yahve'ye sallamalık sunu olarak ondalığın ondalığını sunacaksınız."],["27","Sizin sallamalık sununuz, harman yeri buğdayı ve şarap cenderesinin doluluğu gibi size sayılacak."],["28","Böylece siz de İsrael'in çocuklarından aldığınız ondalıklarınızın hepsinden Yahve'ye sallamalık sunu olarak sunacaksınız; ve ondan Yahve'nin sallamalık sunusunu kâhin Aron'a vereceksiniz."],["29","Aldığınız bütün armağanlardan, sallamalık sunuların en iyi kısımlarını, en kutsalını Yahve'ye sunacaksınız.'”"],["30","“Bu nedenle onlara şunu diyeceksin: 'En iyi kısmını çıkardığınızda, Levililer'e harman mahsulü gibi ve şarap cenderesinin mahsulü gibi sayılacaktır."],["31","Onu siz ve ev halkınız her yerde yiyebilirsiniz. Çünkü Buluşma Çadırı'ndaki hizmetinize karşılık bu sizin ödülünüzdür."],["32","Ondan en iyisini çıkardığınızda, bundan dolayı hiçbir günah yüklenmeyeceksiniz. Ölmemek için İsrael'in çocuklarının kutsal şeylerine saygısızlık etmeyeceksiniz.'”"]],19:[["1","Yahve Moşe ve Aron'la konuşup şöyle dedi:"],["2","“Yahve'nin buyurduğu yasanın kuralı budur. İsrael'in çocuklarına, sana lekesiz, hiçbir kusuru olmayan ve boyunduruk takılmamış kırmızı bir düve getirmelerini söyle."],["3","Onu kâhin Eleazar'a vereceksin; o da onu ordugâhın dışına çıkaracak; biri onu onun önünde kesecek."],["4","Kâhin Eleazar parmağıyla onun kanından biraz alacak ve kanını yedi kez Buluşma Çadırı'nın önüne doğru serpecek."],["5","Birisi düveyi onun gözü önünde yakacak; onun derisini, etini ve kanını gübresiyle birlikte yakacak."],["6","Kâhin sedir ağacını, mercanköşkotu ve kırmızıyı alıp düvenin yakıldığı ateşin ortasına atacak."],["7","Sonra kâhin giysilerini yıkayacak, bedenini suda yıkayacak, sonra ordugâha girecek ve kâhin akşama kadar kirli olacaktır."],["8","Onu yakan kişi giysilerini suda yıkayacak, bedenini de suda yıkayacak ve akşama kadar kirli olacaktır.”"],["9","“Temiz bir adam düvenin külünü toplayacak ve onları ordugâhın dışında, temiz bir yere koyacak; ve kirliliklerini temizleyen suda kullanılmak üzere İsrael'in çocukları topluluğu için saklanacaktır. Bu bir günah sunusudur."],["10","Düvenin külünü toplayan kişi giysilerini yıkayacak ve akşama kadar kirli olacaktır. Bu, İsrael'in çocuklarına ve aralarında garip olarak yaşayan yabancıya sonsuza dek bir kural olacaktır.”"],["11","“Herhangi bir insan ölüsüne dokunan kişi yedi gün kirli olacaktır."],["12","Üçüncü gün suyla arınacak, yedinci gün de temiz olacak; ama kendini üçüncü gün arındırmazsa, o zaman yedinci gün temiz olmayacaktır."],["13","Ölüye, ölmüş birinin bedenine dokunan ve kendini arındırmayan kişi, Yahve'nin konutunu kirletmiş olur; ve o can İsrael'den atılacaktır; üzerine kirlilik suyu serpilmediği için kirli olacaktır. Kirliliği hâlâ üzerindedir.”"],["14","“Bir adam çadırda öldüğünde yasa şudur: Çadıra giren ve çadırda bulunan herkes yedi gün kirli olacaktır."],["15","Üzerinde örtüsü bağlı olmayan her açık kap kirlidir.”"],["16","“Kırda kılıçla öldürülmüş birine, bir ölüye, bir insan kemiğine ya da bir mezara dokunan kişi yedi gün kirli olacaktır.”"],["17","“Kirli kişiler için yakılan günah sunusunun küllerinden alacaklar; ve bir kapta onların üzerine akarsu dökülecektir."],["18","Temiz kişi mercanköşkotu alıp suya batıracak ve çadırın üzerine, bütün kapların üzerine, orada bulunanların üzerine, kemiğe, öldürülmüş insana, ölüye ya da mezara dokunanın üzerine serpecek."],["19","Temiz kişi üçüncü ve yedinci günde kirli olanın üzerine serpecek. Yedinci gün onu arındıracak. Giysilerini yıkayacak, suda yıkanacak ve akşam temiz olacaktır."],["20","Ama kirli olup kendini arındırmayan kişi, Yahve'nin kutsal yerini kirlettiği için topluluğun arasından atılacaktır. Üzerine kirlilik suyu serpilmemiştir. O kirlidir."],["21","Bu onlar için kalıcı bir kural olacaktır. Kirlilik suyu serpen kişi, giysilerini yıkayacak ve kirlilik suyuna dokunan kişi, akşama kadar kirli olacaktır.”"],["22","“Kirli kişinin dokunduğu her şey kirli olacaktır; ve ona dokunan can akşama kadar kirli olacaktır.”"]],20:[["1","İsrael'in çocukları, bütün topluluk birinci ayda Zin Çölü'ne geldiler. Halk Kadeş'te oturdu. Miryam orada öldü ve oraya gömüldü."],["2","Topluluk için su yoktu; Moşe'ye ve Aron'a karşı bir araya toplandılar."],["3","Halk Moşe'yle çekişip şöyle dedi: “Keşke kardeşlerimiz Yahve'nin önünde öldüğü gibi biz de ölseydik!"],["4","Biz ve hayvanlarımız burada ölelim diye neden Yahve'nin topluluğunu bu çöle getirdiniz?"],["5","Bizi bu kötü yere getirmek için neden bizi Mısır'dan çıkardınız? Tohumun, incirlerin, asmaların ya da narların yeri değil; içecek su da yok.”"],["6","Moşe ile Aron topluluğun önünden Buluşma Çadırı'nın kapısına gidip yüzüstü yere kapandılar. Yahve'nin görkemi onlara göründü."],["7","Yahve Moşe'ye şöyle konuştu:"],["8","“Değneği al, sen ve kardeşin Aron'la birlikte topluluğu toplayın ve onların gözleri önünde kayaya, suyunu vermesini söyleyin. Onlara kayadan su çıkaracaksın; böylece topluluğa ve hayvanlarına içecek vereceksin.”"],["9","Moşe, kendisine buyurduğu gibi değneği Yahve'nin önünden aldı."],["10","Moşe ile Aron topluluğu kayanın önünde topladılar ve o onlara şöyle dedi: “Ey siz başkaldıranlar, şimdi dinleyin! Size bu kayadan su çıkaralım mı?”"],["11","Moşe elini kaldırıp değneğiyle kayaya iki kez vurdu ve bol miktarda su çıktı. Topluluk ve hayvanları içti."],["12","Yahve Moşe'yle Aron'a şöyle dedi: “İsrael'in çocuklarının gözünde beni kutsal kılmak için bana inanmadığınızdan bu topluluğu onlara verdiğim ülkeye götürmeyeceksiniz.”"],["13","Bunlar Meriva sularıdır; çünkü İsrael'in çocukları Yahve ile çekiştiler ve O onlarda kutsal kılındı."],["14","Moşe Kadeş'ten Edom Kralı'na ulaklar göndererek şöyle dedi: “Kardeşin İsrael diyor ki: Başımıza gelen bütün sıkıntıları biliyorsun;"],["15","atalarımız Mısır'a indiler, biz de uzun süre Mısır'da yaşadık. Mısırlılar bize ve atalarımıza kötü davrandılar."],["16","Yahve'ye feryat ettiğimizde sesimizi duydu, bir melek göndererek bizi Mısır'dan çıkardı. İşte, biz senin sınırının kenarındaki Kadeş kentindeyiz."],["17","“Lütfen izin ver ülkenden geçelim. Tarladan, bağdan geçmeyeceğiz, kuyu suyundan da içmeyeceğiz. Kralın yolundan gideceğiz. Sınırınızı geçinceye kadar ne sağa ne de sola sapacağız.”"],["18","Edom ona, “Benden geçmeyeceksin, yoksa karşına kılıçla çıkarım” dedi."],["19","İsrael'in çocukları ona, “Ana yoldan yukarı çıkacağız” dediler. “Eğer ben ve hayvanlarım senin suyundan içersek, o zaman bedelini vereceğim. Başka hiçbir şey yapmadan yürüyüp geçmeme izin ver.”"],["20","“Geçmeyeceksin” dedi. Edom birçok kişiyle ve güçlü bir el ile ona karşı çıktı."],["21","Bunun üzerine Edom, İsrael'in kendi sınırından geçmesine izin vermeyi reddetti ve İsrael onun yanından döndü."],["22","Kadeş'ten göç ettiler ve İsrael'in çocukları, bütün topluluk Hor Dağı'na geldiler."],["23","Yahve, Edom ülkesinin sınırındaki Hor Dağı'nda Moşe ve Aron'a şöyle konuştu:"],["24","“Aron halkına kavuşacak; çünkü Meriva sularında sözüme karşı isyan ettiğiniz için İsrael'in çocuklarına verdiğim diyara girmeyecek."],["25","Aron'la oğlu Eleazar'ı al ve onları Hor Dağı'na götür;"],["26","Aron'un giysilerini çıkarıp oğlu Eleazar'a giydir. Aron kavuşturulacak ve orada ölecektir.”"],["27","Moşe Yahve'nin buyurduğu gibi yaptı. Bütün topluluğun gözü önünde Hor Dağı'na çıktılar."],["28","Moşe Aron'un giysilerini çıkarıp oğlu Eleazar'a giydirdi. Aron orada dağın zirvesinde öldü ve Moşe ile Eleazar dağdan indiler."],["29","Aron'un öldüğünü gören bütün topluluk, bütün İsrael evi Aron için otuz gün ağladı."]],21:[["1","Güneyde yaşayan Kenanlı, Arad Kralı, İsrael'in Atarim yolundan geldiğini duydu. İsrael'e karşı savaştı ve onlardan bazılarını esir aldı."],["2","İsrael Yahve'ye adak adayıp şöyle dedi: “Eğer bu halkı gerçekten benim elime verirsen, o zaman kentlerini tamamen yok edeceğim.”"],["3","Yahve İsrael'in sesini duydu ve Kenanlılar'ı teslim etti; onları ve kentlerini tamamen yok ettiler. O yere Horma adı verildi."],["4","Edom ülkesinin etrafından dolanmak için Hor Dağı'ndan, Kızıldeniz yolundan yol aldılar. Yolculuktan dolayı halkın canı çok sıkkındı."],["5","Halk, Tanrı'ya ve Moşe'ye karşı şöyle konuştu: “Çölde ölmemiz için neden bizi Mısır'dan çıkardınız? Çünkü ekmek yok, su yok canımız da bu iğrenç yiyecekten tiksiniyor!”"],["6","Yahve halkın arasına zehirli yılanlar gönderdi, onlar da insanları ısırdılar. İsraelliler'in çoğu öldü."],["7","Halk Moşe'ye gelip şöyle dedi: “Günah işledik, çünkü Yahve'ye ve sana karşı konuştuk. Yılanları bizden uzaklaştırması için Yahve'ye dua et.” Moşe halk için dua etti."],["8","Yahve Moşe'ye şöyle dedi: “Zehirli bir yılan yap ve onu bir direğin üzerine koy. Öyle olacak ki, ısırılan herkes onu görünce yaşayacak.”"],["9","Moşe tunçtan bir yılan yapıp onu direğin üzerine koydu. Eğer bir kişiyi yılan ısırmışsa, o kişi tunç yılana baktığında yaşıyordu."],["10","İsrael'in çocukları yola koyuldular ve Ovot'ta konakladılar."],["11","Ovot'tan ayrılıp gün doğumuna doğru Moav'ın önündeki çölde, İyeavarim'de konakladılar."],["12","Oradan ayrılıp Zered Vadisi'nde konakladılar."],["13","Oradan ayrılıp Arnon Nehri'nin karşı yakasında, Amorlular'ın sınırından çıkan çölde konakladılar. Çünkü Arnon, Moav'la Amorlular arasındaki Moav sınırıdır."],["14","Bu nedenle Yahve'nin Savaşları Kitabı'nda şöyle deniyor: “Vahev, Arnon vadilerindeki Sufa'da,"],["15","vadilerin Ar yerleşkesine doğru uzanan yamacı Moav sınırına kadar dayanır.”"],["16","Oradan Beer'e gittiler; Yahve'nin Moşe'ye, “Halkı topla, onlara su vereceğim” dediği kuyu budur."],["17","Sonra İsrael şu ezgiyi söyledi: “Ey kuyu, fışkır!"],["18","Beylerin kazdığı, halkın ileri gelenlerinin asayla ve sırıklarla kazdıkları kuyuya ezgi söyleyin.” Çölden Mattana'ya;"],["19","Mattana'dan Nahaliel'e; ve Nahaliel'den Bamot'a;"],["20","Bamot'tan Moav kırındaki vadiye, çöle bakan Pisga Tepesi'ne gittiler."],["21","İsrael, Amorlular'ın Kralı Sihon'a ulaklar göndererek şöyle dedi:"],["22","“İzin ver ülkenden geçeyim. Tarlaya, bağa sapmayacağız. Kuyuların suyundan içmeyeceğiz. Sınırından geçinceye kadar kralın yolundan gideceğiz.”"],["23","Sihon İsrael'in kendi sınırından geçmesine izin vermedi; ve Sihon bütün halkını bir araya topladı ve İsrael'e karşı çöle çıkıp Yahesa'ya geldi. İsrael'e karşı savaştı."],["24","İsrael onu kılıçla vurdu ve Arnon'dan Yabbok'a kadar, Ammon'un çocuklarına kadar, onun diyarına sahip oldu; çünkü Ammon'un çocuklarının sınırı güçlüydü."],["25","İsrael bu kentlerin hepsini aldı. İsrael Amorlular'ın bütün kentlerinde, Heşbon'da ve onun bütün köylerinde yaşıyordu."],["26","Çünkü Heşbon, eski Moav Kralı'na karşı savaşan ve Arnon'a kadar bütün ülkesini elinden alan Amorlular'ın Kralı Sihon'un kentiydi."],["27","Bu nedenle özdeyişleri söyleyenler, “Heşbon'a gelin” diyorlar. “Sihon kenti kurulsun ve sağlamlaştırılsın;"],["28","Çünkü Heşbon'dan bir ateş, Sihon kentinden bir alev çıktı. Arnon'un yüksek yerlerinin efendileri Moavlı Ar'ı yiyip bitirdi."],["29","Vay başına, ey Moav! İşiniz bitti, Kemoş halkı! Oğullarını kaçak, kızlarını ise Amorlular'ın kralı Sihon'a sürgüne verdi."],["30","Onlara ok attık. Heşbon, Divon'a kadar yok oldu. Medeva'ya dek uzanan Nofa'ya kadar yerle bir ettik.”"],["31","Böylece İsrael Amorlular'ın diyarında yaşadı."],["32","Moşe Yazer'i araştırmak üzere adamlar gönderdi. Onun köylerini aldılar ve orada bulunan Amorlular'ı kovdular."],["33","Dönüp Başan yoluna çıktılar. Başan Kralı Og, kendisi ve tüm halkı Edrei'de savaşmak için onlara karşı çıktılar."],["34","Yahve Moşe'ye şöyle dedi: “Ondan korkma; çünkü onu, bütün halkıyla ve ülkesiyle birlikte senin eline teslim ettim. Heşbon'da yaşayan Amorlular'ın Kralı Sihon'a yaptığın gibi yapacaksın.”"],["35","Böylece, bir kişi bile sağ kalmayana dek onu, oğullarını ve bütün halkını vurdular; ve onun diyarına sahip oldular."]],22:[["1","İsrael'in çocukları yola çıktılar ve Yarden'in ötesindeki Moav ovalarında, Yeriha yanında konakladılar."],["2","Sippor oğlu Balak, İsrael'in Amorlular'a yaptıklarının tümünü gördü."],["3","Moav bu halktan çok korkuyordu, çünkü çoktular. Moav, İsrael'in çocukları yüzünden sıkıntı çekiyordu."],["4","Moav Midyan'ın ihtiyarlarına şöyle dedi: “Öküzün kır otunu yaladığı gibi, bu kalabalık da çevremizdeki her şeyi yalayacak.” O sırada Sippor oğlu Balak Moav Kralı'ydı."],["5","Beor oğlu Balam'a, onun halkının çocuklarının yaşadığı ülkeye, o Irmak kıyısındaki Petor'a ulaklar göndererek onu çağırmak üzere şöyle dedi: “İşte, Mısır'dan çıkan bir halk var. Bak, yerin yüzünü kaplıyorlar ve karşımda duruyorlar."],["6","Lütfen, şimdi gel de benim için bu halka lanet et; çünkü onlar benden çok güçlüdürler. Belki galip gelirim de onları vururuz ve onları ülkeden kovarım; çünkü senin kutsadığın insanın kutsandığını, lanetlediğin insanın de lanetlendiğini biliyorum.”"],["7","Moav ihtiyarlarıyla Midyan ihtiyarları ellerinde falcılık ödülleriyle yola çıktılar. Balam'a gelip Balak'ın sözlerini ona bildirdiler."],["8","Onlara, “Bu gece burada kalın, Yahve'nin bana söyleyeceği gibi size de haberi bildireceğim” dedi. Moav beyleri Balam'ın yanında kaldı."],["9","Tanrı Balam'a gelip, “Yanındaki bu adamlar kim?” dedi."],["10","Balam Tanrı'ya şöyle dedi: “Moav Kralı Sippor oğlu Balak bana şöyle dedi:"],["11","'İşte, Mısır'dan çıkan halk yerin yüzünü kaplıyor. Şimdi gel de benim için onlara lanet oku. Belki onlara karşı savaşabilir ve onları kovabilirim.'”"],["12","Tanrı Balam'a, “Onlarla gitmeyeceksin” dedi. “O halkı lanetlemeyeceksin, çünkü onlar kutsanmıştır.”"],["13","Balam sabah kalktı ve Balak'ın beylerine şöyle dedi: “Ülkenize gidin; çünkü Yahve sizinle gelmeme izin vermiyor.”"],["14","Moav beyleri kalkıp Balak'a giderek, “Balam bizimle gelmeyi reddediyor” dediler."],["15","Balak yine onlardan daha çok ve daha saygın beyler gönderdi."],["16","Balam'a gelip şöyle dediler: “Sippor oğlu Balak şöyle diyor: 'Lütfen, hiçbir şey bana gelmene engel olmasın."],["17","Çünkü seni büyük bir saygınlıkla yükselteceğim ve bana ne dersen onu yapacağım. Lütfen, gel de benim için bu halka lanet et.'”"],["18","Balam, Balak'ın hizmetkârlarına şöyle yanıt verdi: “Eğer Balak bana altın ve gümüş dolu evini verse bile, az olsun çok olsun, Tanrım Yahve'nin sözünün dışına çıkamam."],["19","Bu nedenle şimdi lütfen, bu gece de burada kalın ki, Yahve'nin bana başka neler söyleyeceğini bileyim.”"],["20","Gece Tanrı Balam'a gelip şöyle dedi: “Eğer adamlar seni çağırmaya geldiyse kalk, onlarla birlikte git; ama yalnızca sana söylediğim sözü yapacaksın.”"],["21","Balam sabah kalktı, eşeğine palan vurdu ve Moav beyleriyle birlikte gitti."],["22","O gittiği için Tanrı'nın öfkesi alevlendi; ve Yahve'nin meleği ona karşı bir düşman olarak yolda dikildi. Eşeğine binmişti ve iki hizmetçisi de yanındaydı."],["23","Eşek, Yahve'nin meleğinin elinde kılıcını çekmiş yolda durduğunu gördü; ve eşek yoldan sapıp tarlanın içine girdi. Balam onu yola döndürmek için eşeğe vurdu."],["24","Yahve'nin meleği üzüm bağları arasındaki dar bir yolda durdu; bu tarafta bir duvar, o tarafta bir duvar vardı."],["25","Eşek Yahve'nin meleğini görünce kendini duvara attı ve Balam'ın ayağını duvara sıkıştırdı. Ona tekrar vurdu."],["26","Yahve'nin meleği daha da ileri gitti, ne sağa ne de sola sapmak için yolun olmadığı dar bir yerde durdu."],["27","Eşek Yahve'nin meleğini görünce Balam'ın altında yattı. Balam'ın öfkesi alevlendi ve değneğiyle eşeğe vurdu."],["28","Yahve eşeğin ağzını açtı ve Balam'a, “Sana ne yaptım da bana böyle üç kez vurdun?” dedi."],["29","Balam eşeğe, “Madem benimle alay ettin, keşke elimde bir kılıç olsaydı, seni şimdi öldürürdüm” dedi."],["30","Eşek Balam'a şöyle dedi: “Bugüne dek bütün ömrün boyunca üzerine bindiğin eşeğin ben değil miyim? Sana böyle yapmışlığım oldu mu hiç?” “Hayır” dedi."],["31","Sonra Yahve Balam'ın gözlerini açtı ve Yahve'nin meleğinin elinde kılıcını çekmiş yolda durduğunu gördü; ve başını eğip yüzüstü yere kapandı."],["32","Yahve'nin meleği ona şöyle dedi: “Eşeğine neden böyle üç kez vurdun? İşte, sana düşman olarak çıktım, çünkü senin yolun önümde sapkındır."],["33","Eşek beni gördü ve üç kez önümden saptı. Eğer önümden sapmamış olsaydı, şimdi seni kesinlikle öldürür, onu da sağ bırakırdım.”"],["34","Balam Yahve'nin meleğine şöyle dedi: “Günah işledim; çünkü bana karşı durduğunu bilmiyordum. Bu nedenle, eğer sen bundan hoşnut değilsen, geri döneceğim.”"],["35","Yahve'nin meleği Balam'a şöyle dedi: “Adamlarla birlikte git; ama yalnızca sana söyleyeceğim sözü söyleyeceksin.” Balam Balak'ın beyleriyle birlikte gitti."],["36","Balak, Balam'ın geldiğini duyunca, onu karşılamak için Arnon sınırında, sınırın en uzak yerindeki Moav Kenti'ne gitti."],["37","Balak, Balam'a şöyle dedi: “Seni çağırtmak için ciddiyetle çağrıda bulunmadım mı? Neden bana gelmedin? Seni gerçekten saygınlık için yükseltmeye ben yeterli değil miyim?”"],["38","Balam Balak'a şöyle dedi: “İşte, sana geldim. Artık bir şey söylemeye gücüm var mı? Tanrı’nın ağzıma koyduğu sözü söyleyeceğim.”"],["39","Balam Balak'la birlikte gitti ve Kiryat-Husot'a geldiler."],["40","Balak sığır ve koyun kurban etti ve Balam'a ve kendisiyle birlikte olan beylere gönderdi."],["41","Sabah Balak Balam'ı alıp Baal'ın yüksek yerlerine götürdü; ve oradan halkın bir kısmını gördü."]],23:[["1","Balam, Balak'a, “Burada bana yedi sunak yap, burada benim için yedi boğayla yedi koç hazırla” dedi."],["2","Balak, Balam'ın söylediği gibi yaptı; ve Balak ile Balam her sunakta bir boğa ve bir koç sundular."],["3","Balam Balak'a, “Yakmalık sunularının yanında dur, ben de gideceğim” dedi. “Belki Yahve benimle buluşmaya gelecektir. Bana ne gösterirse onu sana söyleyeceğim.” Çıplak bir tepeye gitti."],["4","Tanrı Balam'la karşılaştı ve Balam O'na şöyle dedi: “Yedi sunak hazırladım ve her sunakta bir boğayla bir koç sundum.”"],["5","Yahve Balam'ın ağzına bir söz koydu, “Balak'a dön, böylece konuşacaksın” dedi."],["6","Onun yanına döndü ve işte, kendisi ve tüm Moav beyleri yakmalık sunusunun yanında duruyordu."],["7","Benzetmesine şu sözle başladı: “Doğu dağlarındaki Moav Kralı Balak beni Aram'dan getirdi. Gel, benim için Yakov'a lanet et. Gel, İsrael'e meydan oku."],["8","Tanrı'nın lanetlemediğini ben nasıl lanet edeyim? Yahve'nin meydan okumadığına ben nasıl meydan okuyayım?"],["9","Çünkü onu kayaların doruğundan görüyorum. Tepelerden ona bakıyorum. İşte, bu tek başına oturan bir halktır ve ulusların arasında sayılmayacaktır."],["10","Yakov'un tozunu kim sayabilir, İsrael'in dörtte birini hesap edebilir? Doğruların ölümüyle öleyim! Benim sonum onunki gibi olsun!”"],["11","Balak, Balam'a, “Bana ne yaptın?” dedi. “Seni düşmanlarıma lanet etmeye getirdim ve işte, onları, hepsini yalnızca kutsadın.”"],["12","O yanıt verip dedi: “Yahve'nin ağzıma koyduğunu söylemeye dikkat etmem gerekmez mi?”"],["13","Balak ona, “Lütfen benimle birlikte onları görebileceğin başka bir yere gel” dedi. “Sadece bir kısmını göreceksin, hepsini görmeyeceksin. Benim için onlara oradan lanet et.”"],["14","Onu Sofim Kırı'na, Pisga Tepesi'ne götürdü, yedi sunak yaptı, her sunakta bir boğa ve bir koç sundu."],["15","Balak'a, “Ben orada Tanrı'yla buluşurken sen burada, yakmalık sunularının yanında dur” dedi."],["16","Yahve Balam'la karşılaştı ve onun ağzına bir söz koyup, “Balak'a dön ve şunu söyle” dedi."],["17","Onun yanına geldi ve işte, kendisi ve Moav beyleri de yakmalık sunusunun yanında duruyordu. Balak ona, “Yahve ne söyledi?” dedi."],["18","Benzetmesini sürdürüp şöyle dedi: “Kalk, ey Balak, ve dinle! Dinle beni, ey Sippor oğlu."],["19","Tanrı bir insan değil ki, yalan söylesin, insanoğlu değil ki, düşüncesini değiştirsin. O söyler de yapmaz mı? Ya da konuşur da gerçekleştirmez mi?"],["20","İşte, kutsamak için buyruk aldım. O kutsadı, ben de geri çeviremem."],["21","Yakov'da kötülük görmedi. İsrael'de de sapkınlık görmedi. Tanrısı Yahve onunladır. Bir kralın haykırışı onların arasındadır."],["22","Tanrı onları Mısır'dan çıkarıyor. Yaban öküzü gibi gücü var."],["23","Kesinlikle Yakov'a büyü tutmaz; İsrael'e fal işlemez. Şimdi Yakov ve İsrael için, 'Tanrı neler yaptı?' denilecektir."],["24","İşte, bir halk dişi aslan gibi kalkıyor. Bir aslan gibi kendini yukarı kaldırıyor. Avının etini yemeden ve öldürülenlerin kanını içmeden yatmayacaktır.”"],["25","Balak, Balam'a, “Onlara ne hiç lanet et, ne de onları hiç kutsa” dedi."],["26","Ama Balam Balak'a şu karşılığı verdi: “Ben sana, 'Yahve ne söylerse hepsini yapmalıyım' demedim mi?”"],["27","Balak, Balam'a, “Şimdi gel, seni başka bir yere götüreyim” dedi. “Belki oradan benim için onlara lanet etmenden Tanrı hoşnut olur.''"],["28","Balak, Balam'ı çöle bakan Peor Tepesi'ne götürdü."],["29","Balam Balak'a, “Burada bana yedi sunak yap, burada benim için yedi boğayla yedi koç hazırla” dedi."],["30","Balak, Balam'ın söylediklerini yaptı ve her sunakta bir boğayla bir koç sundu."]],24:[["1","Balam, Yahve'nin İsrael'i kutsamaktan hoşnut olduğunu görünce, diğer seferler olduğu gibi kehanete başvurmak yerine yüzünü çöle çevirdi."],["2","Balam gözlerini kaldırdı ve İsrael'in oymaklarına göre oturduğunu gördü; ve onun üzerine Tanrı'nın Ruhu geldi."],["3","Benzetmesini şöyle sürdürdü ve dedi: “Beor oğlu Balam diyor ki, gözleri açık olan adam diyor ki;"],["4","Tanrı'nın sözlerini duyan, Her Şeye Gücü Yeten'in görümünü gören, yere kapanıp gözleri açılmış olan şöyle diyor:"],["5","Çadırların ne kadar güzel, ey Yakov, konutların da, ey İsrael!"],["6","Vadiler gibi, ırmak kıyısındaki bahçeler gibi, Yahve'nin diktiği öd ağaçları gibi, su kıyısındaki sedir ağaçları gibi yayıldılar."],["7","Onun kovalarından su akacaktır. Onun tohumu birçok sularda olacaktır. Onun Kralı Agag'dan daha üstün olacaktır. Onun krallığı yüceltilecektir."],["8","Tanrı onu Mısır'dan çıkarıyor. Onun yaban öküzü gibi gücü var. Düşmanları olan ulusları tüketecek, kemiklerini kıracak ve oklarıyla onları delecektir."],["9","Çömeldi, aslan gibi yattı, dişi aslan gibi; onu kim kaldıracak? Seni kutsayan herkes kutsansın. Seni lanetleyen herkes lanetlensin.”"],["10","Balak'ın öfkesi Balam'a karşı alevlendi ve ellerini birbirine vurdu. Balak, Balam'a şöyle dedi: “Seni düşmanlarıma lanet etmeye çağırdım ve işte, onları bu üç keredir yalnızca kutsadın."],["11","Bu nedenle şimdi yerine koş! Seni büyük bir saygınlıkla yükseltmeyi düşünmüştüm; ama işte, Yahve seni saygınlıktan yoksun bıraktı.”"],["12","Balam Balak'a şöyle dedi: “Bana gönderdiğin ulaklarına:"],["13","'Eğer Balak bana altın ve gümüş dolu evini verse bile, kendi fikrimle iyilik ya da kötülük etmek için Yahve'nin sözünün dışına çıkamam. Yahve'nin söylediğini söyleyeceğim' diye dememiş miydim?"],["14","İşte şimdi halkımın yanına gidiyorum. Gel, bu halkın son günlerde senin halkına ne yapacaklarını sana bildireyim.”"],["15","Benzetmesini şöyle sürdürdü ve dedi: “Beor oğlu Balam diyor ki, gözleri açık olan adam şöyle diyor;"],["16","Tanrı'nın sözlerini duyan, Yüceler Yücesi'nin bilgisini bilen ve yere kapanıp gözleri açık olarak Her Şeye Gücü Yeten'in görümünü gören şöyle diyor:"],["17","Onu görüyorum, ama şimdi değil. Ona bakıyorum ama yakın değil. Yakov'dan bir yıldız çıkacak. İsrael'den bir asa yükselecek, Moav'ı dört bir yanından vuracak ve Şet'in bütün oğullarını ezecek."],["18","Edom mülk olacak. İsrael yiğitçe bunu yaparken, düşmanı Seir de mülk olacak."],["19","Yakov'dan biri hüküm sürecek, ve kentte artakalanları yok edecek.”"],["20","Amalek'e baktı, benzetmesini sürdürüp şöyle dedi: “Amalek ulusların birincisiydi, ama onun sonu yıkım olacak.”"],["21","Kenli'ye baktı ve benzetmesini sürdürüp şöyle dedi: “Mesken yerin güçlüdür. Senin yuvan kaya içine koyulmuştur."],["22","Yine de Aşur seni tutsak alana dek Keni harap olacaktır.”"],["23","Benzetmesini sürdürdü ve şöyle dedi: “Ne yazık ki, Tanrı bunu yaptığı zaman kim yaşayacak?"],["24","Ama Kittim kıyısından gemiler gelecek. Aşur'u ve Ever'i sarsacaklar. O da yıkıma uğrayacaktır.”"],["25","Balam kalkıp gitti ve yerine döndü; Balak da kendi yoluna gitti."]],25:[["1","İsrael Şittim'de kaldı; ve halk Moav kızlarıyla zina yapmaya başladı;"],["2","çünkü halkı kendi ilâhlarına kurban sunmaya çağırıyorlardı. Halk yedi ve onların ilâhlarına eğildiler."],["3","İsrael Baal Peor'a bağlandı ve Yahve'nin öfkesi İsrael'e karşı alevlendi."],["4","Yahve Moşe'ye şöyle dedi: “Halkın bütün ileri gelenlerini al ve onları güneşe karşı Yahve'nin önünde as ki, Yahve'nin kızgın öfkesi İsrael'den dönsün.”"],["5","Moşe İsrael hâkimlerine şöyle dedi: “Herkes Baal Peor'a bağlanan adamlarını öldürsün.”"],["6","İşte, İsrael'in çocuklarından biri geldi, Moşe'nin gözü önünde, Buluşma Çadırı kapısında ağlamakta olan bütün İsrael'in çocuklarının bütün topluluğu gözü önünde kardeşlerine Midyanlı bir kadın getirdi."],["7","Kâhin Aron'un oğlu Eleazar'ın oğlu Pinehas bunu görünce topluluğun ortasından kalktı ve eline bir mızrak aldı."],["8","İsraelli adamın peşinden çadıra girdi ve ikisini de, İsraelli adamın da, kadının da bedeninden mızrağı sapladı. Böylece İsrael'in çocukları arasındaki veba durduruldu."],["9","Vebadan ölenler yirmi dört bindi."],["10","Yahve Moşe'ye şöyle konuştu:"],["11","“Kâhin Aron'un oğlu, Eleazar'ın oğlu Finehas, aralarındaki kıskançlığımla kıskandığı için İsrael'in çocuklarından gazabımı döndürdü, bundan ötürü İsrael'in çocuklarını kıskançlığımla tüketmedim."],["12","Bu nedenle söyle, 'İşte, ona esenlik antlaşmamı veriyorum."],["13","Kendisi ve kendisinden sonra soyu için sonsuz bir kâhinlik antlaşması olacaktır; çünkü o, Tanrı için kıskandı ve İsrael'in çocukları için kefaret etti.'”"],["14","İsraelli adamın adı, Midyanlı kadınla birlikte öldürülen kişi, Şimon'un oğulları ata evinin beyi Salu oğlu Zimri'ydi."],["15","Öldürülen Midyanlı kadının adı Sur'un kızı Kozbi'ydi. Midyan'daki bir ata evi halkının beyiydi."],["16","Yahve Moşe'ye şöyle dedi:"],["17","“Midyanlılar'ı sıkıştır ve onları vur;"],["18","çünkü Peor meselesinde hileleriyle sizi sıkıştırdılar; Peor meselesinde ve veba gününde öldürülen kız kardeşleri Midyan beyinin kızı Kozbi ile ilgili olayda sizi aldattılar.”"]],26:[["1","Vebadan sonra Yahve Moşe'ye ve kâhin Aron oğlu Eleazar'a şöyle dedi:"],["2","“Atalarının evlerine göre yirmi yaş ve üzeri İsrael'in çocuklarından tüm topluluğu, İsrael'de savaşa çıkabileceklerin tümünü sayın.”"],["3","Moşe ile Kâhin Eleazar, Yarden yanında, Yeriha'daki Moav ovalarında onlarla konuşup şöyle dediler:"],["4","“Yahve'nin Moşe'ye ve İsrael'in çocuklarına buyurduğu gibi, yirmi yaş ve yukarısını sayın.” Bunlar Mısır diyarından çıkanlardır."],["5","İsrael'in ilk oğlu Ruven; Ruven'in oğulları: Hanok'tan Hanokiler soyu; Pallu'dan Palluliler soyu;"],["6","Hetsron'dan Hetsroniler soyu; Karmi'den Karmiler soyu."],["7","Ruvenliler'in soyları bunlardır; ve onlardan sayılanlar kırk üç bin yedi yüz otuz kişiydi."],["8","Pallu'nun oğlu: Eliav."],["9","Eliav'ın oğulları: Nemuel, Datan ve Aviram. Bunlar, Yahve'ye başkaldırdıklarında Korah'ın yanında Moşe'ye ve Aron'a başkaldıran, topluluk tarafından çağrılan Datan ve Aviram'dır;"],["10","ve o topluluk öldüğünde, yer ağzını açıp Korah'la birlikte onları da yutmuştu; o sırada ateş iki yüz elli kişiyi yakıp tüketti ve onlar bir belirti haline geldiler."],["11","Ne var ki, Korah'ın oğulları ölmedi."],["12","Şimon'un oğulları soylarına göre: Nemuel'den Nemuelliler soyu; Yamin'den Yaminiler soyu; Yakin'den Yakiniler soyu;"],["13","Zerah'tan Zerahiler soyu; Şaul'dan Şauliler soyu."],["14","Şimoniler'in soyları bunlardır; yirmi iki bin iki yüz."],["15","Soylarına göre Gad'ın oğulları: Sefon'dan Sefoniler soyu; Haggi'den Haggililer soyu; Şuni'den Şunililer soyu;"],["16","Ozni'den Ozniniler soyu; Eri'den Erililer soyu;"],["17","Arod'tan Arodiler soyu; Areli'den Areliler soyu."],["18","Gadoğulları'ndan sayılanlara göre soyları bunlardır, kırk bin beş yüz."],["19","Yahuda'nın oğulları: Er ve Onan. Er ve Onan Kenan diyarında öldüler."],["20","Soylarına göre Yahuda'nın oğulları: Şela'dan Şelaniler soyları; Peres'ten Peresiler soyu; Zerah'tan Zerahiler soyu."],["21","Peres'in oğulları: Hetsron'dan Hetsroniler soyu; Hamul'dan Hamuliler soyu."],["22","Onlardan sayılanlara göre Yahuda soyları bunlardır; yetmiş altı bin beş yüz."],["23","Soylarına göre İssakar'ın oğulları: Tola'dan Tolaliler soyu; Puva'dan Puniler soyu;"],["24","Yaşuv'dan Yaşuviler soyu; Şimron'dan Şimroniler soyu."],["25","Onlardan sayılanlara göre İssakar'ın soyları bunlardır; altmış dört bin üç yüz."],["26","Soylarına göre Zevulun'un oğulları: Sered'ten Serediler soyu; Elon'dan Eloniler soyu; Yahleel'den Yahleeliler soyu."],["27","Sayılanlara göre Zevuluniler soyları bunlardır, altmış bin beş yüz."],["28","Soylarına göre Yosef'in oğulları: Manaşşe ve Efraim."],["29","Manaşşe'nin oğulları: Makir'den Makiriler soyu; ve Makir Gilad'ın babası oldu; Gilad'tan Giladlılar soyu."],["30","Gilad'ın oğulları şunlardır: İezer'den İezerliler soyu; Helek'ten Helekiler soyu;"],["31","ve Asriel'den Asrieliler soyu; ve Şekem'den Şekemiler soyu;"],["32","ve Şemida'dan Şemidailer soyu; ve Hefer'den Heferiler soyu."],["33","Hefer oğlu Zelofehad'ın oğlu yoktu, yalnızca kızları vardı; ve Selofhad'ın kızlarının adları Mahla, Nuh, Hogla, Milka ve Tirsa idi."],["34","Manaşşe'nin soyları bunlardır. Onlardan sayılanlar elli iki bin yedi yüz."],["35","Soylarına göre Efraim'in oğulları şunlardır: Şutelah'tan Şutelahiler soyu; Beker'den Bekeriler soyu; Tahan'dan Tahaniler soyu."],["36","Şutelah'ın oğulları şunlardır: Eran'dan Eraniler soyu."],["37","Efraimoğulları'ndan sayılanlara göre soyları bunlardır, otuz iki bin beş yüz. Bunlar soylarına göre Yosef'in oğullarıdır."],["38","Soylarına göre Benyamin'in oğulları: Bela'dan Belailer soyu; Aşbel'den Aşbeliler soyu; Ahiram'dan Ahiramiler soyu;"],["39","Şufam'dan Şufamiler soyu; Hufam'dan Hufamiler soyu."],["40","Bela'nın oğulları Ard ve Naaman'dı; Ardiler soyu; ve Naaman'dan Naamiler soyu."],["41","Soylarına göre Benyamin'in oğulları şunlardır; ve onlardan sayılanlar kırk beş bin altı yüz."],["42","Soylarına göre Dan'ın oğulları şunlardır: Şuham'dan Şuhamiler soyu. Bunlar soylarına göre Dan'ın soylarıdır."],["43","Kendilerinden sayılanlara göre Şuhamiler'in bütün soyları altmış dört bin dört yüz."],["44","Soylarına göre Aşer'in oğulları: Yimna'dan Yimniler soyu; Yişvi'den Yişviler soyu; Beria'dan Berililer soyu."],["45","Beria'nın oğullarından: Heber'den Heberiler soyu; Malkiel'den Malkieliler soyu."],["46","Aşer'in kızının adı Serah'tı."],["47","Sayılanlara göre Aşeroğulları'nın soyları bunlardır; elli üç bin dört yüz."],["48","Soylarına göre Naftali'nin oğulları: Yahseel'den Yahseeliler soyu; Guni'den Guniler soyu;"],["49","Yeser'den Yeseriler soyu; Şillem'den Şillemiler soyu."],["50","Soylarına göre Naftali soyları şunlardır; ve onlardan sayılanlar kırk beş bin dört yüz kişiydi."],["51","İsrael'in çocuklarından sayılanlar bunlardır; altı yüz bin yedi yüz otuz."],["52","Yahve Moşe'ye şöyle dedi:"],["53","“Ülke adlarının sayısına göre miras olarak bunlara bölünecektir."],["54","Daha çok olana daha çok miras verecekseniz, daha az olana daha az miras vereceksiniz. Kendisinden sayılanlara göre herkese mirası verilecektir."],["55","Bununla birlikte ülke kurayla bölünecek. Ata oymaklarının adlarına göre miras alacaklar."],["56","Mirasları çok olanla az olan arasında kuraya göre bölünecektir.”"],["57","Levililer'den soylarına göre sayılanlar şunlardı: Gerşon'dan Gerşoniler soyu; Kohat'tan Kohatiler soyu; Merari'den Merariler soyu."],["58","Levi soyları şunlardır: Livnî soyu, Hevronî soyu, Mahliler soyu, Muşîler soyu ve Korahîler soyu. Kohat Amram'ın babası oldu."],["59","Amram'ın karısının adı Levi'nin Mısır'da doğan kızı Yokevet'ti. Amram'a Aron'u, Moşe'yi ve kız kardeşleri Miryam'ı doğurdu."],["60","Aron'a Nadav, Avihu, Eleazar ve İtamar doğdu."],["61","Nadav ile Avihu, Yahve'nin önünde yabancı ateş sundukları zaman öldüler."],["62","Onlardan sayılanlar, bir aylık ve daha yukarı hepsi erkek olmak üzere, yirmi üç bin kişiydi; çünkü İsrael'in çocukları arasında sayılmadılar, çünkü İsrael'in çocukları arasında onlara miras verilmedi."],["63","Bunlar, Yarden yanında, Yeriha'daki Moav ovalarında İsrael'in çocuklarını sayan Moşe ve Kâhin Eleazar'ın saydıkları kişilerdir."],["64","Ancak bunların arasında, Sina Çölü'nde İsrael'in çocuklarını saymış olan Moşe ve Kâhin Aron'un saydıklarından kimse yoktu."],["65","Çünkü Yahve onlar hakkında, “Kesinlikle çölde ölecekler” demişti. Onlardan Yefunne oğlu Kalev ile Nun oğlu Yeşu dışında kimse kalmamıştı."]],27:[["1","Bunun üzerine Yosef'in oğlu Manaşşe soylarından Manaşşe oğlu Makir oğlu Gilad oğlu Hefer oğlu Selofhad'ın kızları yaklaştı. Kızlarının adları şunlardır: Mahla, Nuh, Hogla, Milka ve Tirsa."],["2","Moşe'nin, Kâhin Eleazar'ın, beylerin ve bütün topluluğun önünde Buluşma Çadırı'nın kapısında durup şöyle dediler:"],["3","“Babamız çölde öldü. O, Korah'ın yanında Yahve'ye karşı toplananların arasında değildi, ama kendi günahı içinde öldü. Oğulları yoktu."],["4","Oğlu olmadığı için babamızın adı neden soyu arasından kaldırılsın? Bize babamızın kardeşleri arasında bir mülk verin.”"],["5","Moşe onların davasını Yahve'nin önüne götürdü."],["6","Yahve Moşe'ye şöyle dedi:"],["7","“Selofhad'ın kızları doğru söylüyor. Babalarının kardeşleri arasında onlara mutlaka miras vereceksin. Babalarının mirasını onlara geçireceksin."],["8","İsrael'in çocuklarına söyleyip diyeceksin, 'Eğer bir adam oğlu olmadan ölürse, onun mirası onun kızına geçecektir."],["9","Kızı yoksa mirasını kardeşlerine vereceksiniz."],["10","Kardeşi yoksa mirasını babasının kardeşlerine vereceksiniz."],["11","Babasının erkek kardeşi yoksa, mirasını soyundan kendisine en yakın olan akrabasına vereceksiniz ve o da onun mülkü olacak. Bu, Yahve'nin Moşe'ye buyurduğu gibi İsrael'in çocukları için bir kural ve ilke olacaktır.'”"],["12","Yahve Moşe'ye şöyle dedi: “Bu Havarim Dağı'na çık ve İsrael'in çocuklarına verdiğim ülkeyi gör."],["13","Onu gördükten sonra, kardeşin Aron gibi sen de halkına kavuşacaksın."],["14","Çünkü topluluğun çekişmesi sırasında, Zin Çölü'nde, onların gözleri önünde beni sularda kutsal sayma sözüme karşı başkaldırdın.'' (Bunlar Zin Çölü'ndeki Kadeş'te Meriva sularıdır.)"],["15","Moşe Yahve'ye şöyle dedi:"],["16","“Bütün insanların ruhlarının Tanrısı Yahve, topluluğun başına bir adam atasın;"],["17","o da onların önünden çıksın, onların önünden girsin, onları dışarı çıkarsın, onları içeri de getirsin ki, Yahve'nin topluluğu çobansız koyunlar gibi olmasın.”"],["18","Yahve Moşe'ye şöyle dedi: “Kendisinde Ruh bulunan Nun oğlu Yeşu'yu al ve elini onun üzerine koy."],["19","Onu kâhin Eleazar'ın ve tüm topluluğun önüne çıkar; ve onu onların gözü önünde görevlendir."],["20","Ona yetki vereceksin ki, İsrael'in çocuklarının bütün topluluğu itaat etsinler."],["21","Urim'in kararına göre Yahve'nin önünde onun için soracak olan Kâhin Eleazar'ın önünde duracak. Hem kendisi, hem de onunla birlikte bütün İsrael'in çocukları, bütün topluluk, onun sözü üzerine çıkacaklar ve onun sözü üzerine içeri girecekler.”"],["22","Moşe Yahve'nin kendisine buyurduğu gibi yaptı. Yeşu'yu alıp kâhin Eleazar'ın ve bütün topluluğun önünde durdurdu."],["23","Yahve'nin Moşe aracılığıyla söylediği gibi ellerini onun üzerine koydu ve onu görevlendirdi."]],28:[["1","Yahve Moşe'ye şöyle dedi:"],["2","“İsrael'in çocuklarına buyur ve onlara de: 'Ateşle yapılan sunular yiyeceğimi, hoş koku olarak, zamanı geldiğinde bana sunmaya dikkat edin.'"],["3","Onlara şöyle diyeceksin: 'Yahve'ye sunacağınız ateşle yapılan sunu şudur: Sürekli yakmalık sunu olarak her gün iki baş olmak üzere bir yaşında kusursuz erkek kuzular."],["4","Kuzulardan birini sabah, diğerini akşam sunacaksın,"],["5","ekmek sunusu olarak hinin dörtte biri kadar dövülmüş yağla yoğrulmuş onda bir efa ince un sunacaksın."],["6","Bu, hoş koku olarak Sina Dağı'nda atanmış sürekli yakmalık sunudur, Yahve'ye ateşle yapılan bir sunudur."],["7","Onun dökmelik sunusu her kuzu için bir hinin dörtte biri kadar olacaktır. Kutsal Yerde Yahve'ye dökmelik sunu olarak ağır içkiden dökeceksin."],["8","Diğer kuzuyu akşam üstü sunacaksın. Sabahın ekmek sunusu gibi, onun dökmelik sunusu gibi, onu Yahve'ye hoş koku olarak, ateşle yapılan sunu olarak sunacaksın.”"],["9","“'Şabat Günü, bir yaşında kusursuz iki erkek kuzu, ekmek sunusu olarak yağla yoğrulmuş onda iki efa ince un ve onun dökmelik sunusunu sunacaksın."],["10","Sürekli yakmalık sunuya ve onun dökmelik sunusuna ek olarak, her Şabat'ın yakmalık sunusu budur.”'"],["11","“'Aylarınızın başında Yahve'ye yakmalık sunu sunacaksınız: İki genç boğa, bir koç, bir yaşında kusursuz yedi erkek kuzu,"],["12","ve her boğa için, ekmek sunusu olarak yağla yoğrulmuş efanın onda üçü ince un; ve bir koç için, ekmek sunusu olarak yağla yoğrulmuş efanın onda ikisi ince un;"],["13","ve her kuzu için ekmek sunusu olarak yağla yoğrulmuş efanın onda biri ince un, yakmalık sunu, hoş koku olarak Yahve'ye ateşle yapılan sunu sunacaksınız."],["14","Onların dökmelik sunuları olarak boğa için yarım hin şarap, koç için hinin üçte biri ve kuzu için hinin dörtte biri kadar şarap olacak. Bu, yılın ayları boyunca her ayın yakmalık sunusudur."],["15","Sürekli yakmalık sunu ve dökmelik sunuya ek olarak Yahve'ye günah sunusu olarak bir teke de sunulacaktır.'”"],["16","“'Birinci ayın on dördüncü günü Yahve'nin Pesah'ıdır."],["17","Bu ayın on beşinci günü bayram olacaktır. Yedi gün mayasız ekmek yenilecektir."],["18","İlk gün kutsal toplantı yapılacak. Olağan hiçbir iş yapmayacaksınız;"],["19","yalnızca Yahve'ye ateşte yapılan sunu olarak yakmalık sunu sunacaksınız: İki genç boğa, bir koç ve bir yaşında yedi erkek kuzu. Onlar kusursuz olacaklar,"],["20","onların ekmek sunusuyla birlikte, yağla yoğrulmuş ince un. Boğa için onda üç, koç için onda iki sunacaksınız."],["21","Yedi kuzunun her kuzusu için onda birini;"],["22","ve günah sunusu olarak sizin için kefaret etmek üzere bir teke sunacaksınız."],["23","Sürekli yakmalık sunu olarak sunulan sabah yakmalık sunularına ek olarak bunları da sunacaksınız."],["24","Böylece, Yahve'ye hoş koku olarak, ateşle yapılan sununun yiyeceğini her gün, yedi gün boyunca sunacaksınız. Sürekli yakmalık sunu ve dökmelik sunuya ek olarak sunulacaktır."],["25","Yedinci gün kutsal toplantı olacaktır. Olağan hiçbir iş yapmayacaksınız.'”"],["26","“'İlk ürünler günü, Haftalar Bayramı'nda Yahve'ye yeni ekmek sunusu sunduğunuz zaman, sizin için kutsal bir toplantı da olacaktır. Olağan hiçbir iş yapmayacaksınız;"],["27","ama Yahve'ye hoş koku, yakmalık sunu olarak: İki genç boğa, bir koç, bir yaşında yedi erkek kuzu;"],["28","ve onların ekmek sunusu, yağla yoğrulmuş ince un, her boğa için onda üç, bir koç için onda iki,"],["29","yedi kuzunun her kuzusu için onda bir;"],["30","ve sizin için kefaret etmek üzere bir de teke sunacaksınız."],["31","Sürekli yakmalık sunu ve ekmek sunusu dışında, bunları ve onların dökmelik sunuları da sunacaksınız. Onların kusursuz olmasına dikkat edin.'”"]],29:[["1","“'Yedinci ayın birinci günü kutsal toplantınız olacak; olağan hiçbir iş yapmayacaksın. Bu size boru çalma günüdür."],["2","Yahve'ye hoş koku, yakmalık sunu olarak: Bir genç boğa, bir koç, bir yaşında kusursuz yedi erkek kuzu;"],["3","ve bunların ekmek sunuları olarak, yağla yoğrulmuş ince un; boğa için onda üç, koç için onda iki,"],["4","ve yedi kuzunun her kuzusu için onda bir;"],["5","ve günah sunusu olarak sizin için kefaret etmek üzere bir teke sunacaksınız;"],["6","bu, yakmalık sunuyla birlikte yeni ay sunusuna, onun ekmek sunusuyla sürekli yakmalık sunuya ve usulüne göre hoş koku için dökmelik sunulara ek olarak, Yahve'ye ateşle yapılan bir sunudur.'”"],["7","“'Bu yedinci ayın onuncu günü kutsal toplantınız olacak. Canlarınıza acı çektireceksiniz. Hiçbir iş yapmayacaksınız;"],["8","yalnızca hoş koku olarak Yahve'ye yakmalık sunu olarak: Bir genç boğa, bir koç, bir yaşında yedi erkek kuzu; hepsi kusursuz olacaklar;"],["9","ve bunların ekmek sunusu olarak, yağla yoğrulmuş ince un; boğa için onda üç, bir koç için onda iki,"],["10","yedi kuzunun her kuzusu için onda bir;"],["11","günah sunusu olarak bir teke sunacaksınız; bu, kefaret günah sunusuna, sürekli yakmalık sunuya, onun ekmek sunusuna ve onun dökmelik sunularına ektir.'”"],["12","“'Yedinci ayın on beşinci günü kutsal toplantınız olacaktır. Olağan hiçbir iş yapmayacaksınız. Yedi gün Yahve'ye bayram tutacaksınız."],["13","Yakmalık sunu, ateşle yapılan sunu, hoş kokulu olarak, on üç genç boğa, iki koç, bir yaşında on dört erkek kuzu; hepsi kusursuz olacaklar;"],["14","ve bunların ekmek sunusu olarak, yağla yoğrulmuş ince un; on üç boğadan her boğa için onda üç, iki koçtan her koç için onda iki,"],["15","ve on dört kuzunun her kuzusu için onda biri;"],["16","günah sunusu olarak bir teke sunacaksınız; bu, sürekli yakmalık sunuya, onun ekmek sunusuna ve onun dökmelik sunusuna ektir.'”"],["17","“'İkinci gün on iki genç boğa, iki koç ve bir yaşında kusursuz on dört erkek kuzu sunacaksınız;"],["18","ve bunların sayısına göre, usulüne göre, boğalar, koçlar ve kuzular için onların ekmek sunusunu ve onların dökmelik sunularını;"],["19","günah sunusu olarak bir teke sunacaksınız; bu, sürekli yakmalık sunuya, onun ekmek sunusuna ve onun dökmelik sunusuna ektir.'”"],["20","“'Üçüncü gün on bir boğa, iki koç, bir yaşında kusursuz on dört erkek kuzu;"],["21","ve bunların sayısına göre, usulüne göre, boğalar, koçlar ve kuzular için onların ekmek sunusunu ve onların dökmelik sunularını;"],["22","günah sunusu olarak bir teke sunacaksınız; bu, sürekli yakmalık sunuya, onun ekmek sunusuna ve onun dökmelik sunusuna ektir.'”"],["23","“'Dördüncü günde on boğa, iki koç, bir yaşında kusursuz on dört erkek kuzu;"],["24","ve bunların sayısına göre, usulüne göre, boğalar, koçlar ve kuzular için onların ekmek sunusunu ve onların dökmelik sunularını;"],["25","günah sunusu olarak bir teke sunacaksınız; bu, sürekli yakmalık sunuya, onun ekmek sunusuna ve onun dökmelik sunusuna ektir.'”"],["26","“'Beşinci gün dokuz boğa, iki koç, bir yaşında kusursuz on dört erkek kuzu;"],["27","ve bunların sayısına göre, usulüne göre, boğalar, koçlar ve kuzular için onların ekmek sunusunu ve onların dökmelik sunularını;"],["28","günah sunusu olarak bir teke sunacaksınız; bu, sürekli yakmalık sunuya, onun ekmek sunusuna ve onun dökmelik sunusuna ektir.'”"],["29","“'Altıncı gün sekiz boğa, iki koç, bir yaşında kusursuz on dört erkek kuzu;"],["30","ve bunların sayısına göre, usulüne göre, boğalar, koçlar ve kuzular için onların ekmek sunusunu ve onların dökmelik sunularını;"],["31","günah sunusu olarak bir teke sunacaksınız; bu, sürekli yakmalık sunuya, onun ekmek sunusuna ve onun dökmelik sunusuna ektir.'”"],["32","“'Yedinci gün: Yedi boğa, iki koç, bir yaşında kusursuz on dört erkek kuzu;"],["33","ve bunların sayısına göre, usulüne göre, boğalar, koçlar ve kuzular için onların ekmek sunusunu ve onların dökmelik sunularını;"],["34","günah sunusu olarak bir teke sunacaksınız; bu, sürekli yakmalık sunuya, onun ekmek sunusuna ve onun dökmelik sunusuna ektir.'”"],["35","“'Sekizinci gün kutsal toplanmanız olacaktır. Olağan hiçbir iş yapmayacaksınız;"],["36","yalnız yakmalık sunu, ateşte yapılan sunu, hoş koku olarak Yahve'ye, bir boğa, bir koç, bir yaşında kusursuz yedi erkek kuzu;"],["37","bunların sayısına göre, usulüne göre, boğa için, koç için ve kuzular için onların ekmek sunusunu ve onların dökmelik sunularını;"],["38","günah sunusu olarak bir teke sunacaksınız; bu, sürekli yakmalık sunuya, onun ekmek sunusuna ve onun dökmelik sunusuna ektir."],["39","“'Yakmalık sunularınız, ekmek sunularınız, dökmelik sunularınız ve esenlik sunularınız olarak, adaklarınızın ve gönüllü sunularınızın yanısıra, bunları da belirlenen bayramlarınızda Yahve'ye sunacaksınız.'”"],["40","Moşe Yahve'nin kendisine buyurduğu her şeye göre İsrael'in çocuklarına söyledi."]],30:[["1","Moşe İsrael'in çocuklarının oymak başlarıyla konuşup şöyle dedi: “Yahve'nin buyurduğu şey şudur."],["2","Bir adam Yahve'ye adak adadığında, ya da canını bir bağla bağlayacağına dair ant içtiğinde, sözünden dönmeyecektir. Ağzından çıkan her şeye göre yapacaktır.”"],["3","“Bir kadın da gençliğinde babasının evindeyken Yahve'ye adak adadığında ve kendisini bir sözle bağladığında,"],["4","ve babası onun canını bağladığı adağı ve sözü duyar; ona hiçbir şey söylemezse, bütün adakları geçerli olacak ve canını bağladığı her söz yerinde duracaktır."],["5","Ama eğer babası duyduğu gün onu yasaklarsa, onun canını bağladığı adakların ya da verdiği sözlerin hiçbiri geçerli olmayacaktır. Babası onu yasakladığı için Yahve onu bağışlayacaktır.”"],["6","“Eğer adakları, ya da canının bağladığı dudaklarının aceleci sözleri üzerindeyken kocaya varırsa,"],["7","ve kocası bunu duyarsa ve duyduğu gün ona hiçbir şey söylemezse; o zaman onun adakları geçerli olacak ve canını bağladığı sözleri yerinde duracaktır."],["8","Ama kocası bunu duyduğu gün onu yasaklarsa, o zaman onun üzerine olan adağını ve canını bağladığı dudaklarının aceleci sözlerini geçersiz kılmış olur. Yahve onu bağışlayacaktır.”"],["9","“Ancak dul kadının ya da boşanmış kadının adağı, canını bağladığı her şey ona karşı olacaktır.”"],["10","“Eğer kadın kocasının evinde adak adadıysa, ya da canını bir antla bağladıysa,"],["11","ve kocası bunu duyduysa, ona karşı sessiz kaldıysa ve ona engel olmadıysa, o zaman onun bütün adakları geçerli olacak ve canını bağladığı her söz yerinde duracaktır."],["12","Ama eğer kocası duyduğu gün bunları geçersiz kıldıysa, o zaman onun adaklarıyla ya da canının bağıyla ilgili olarak ağzından çıkan hiçbir şey geçerli olmayacaktır. Kocası bunları geçersiz kılmıştır. Yahve onu bağışlayacaktır."],["13","Canı yaralayan her adak ve bağlayan andı kocası yerine getirebilir, ya da kocası onu geçersiz kılabilir."],["14","Ama eğer kocası günden güne geçerken ona bir şey söylemezse, o zaman kocası onun üzerine olan bütün adaklarını ya da verdiği bütün sözlerini sağlamlaştırmıştır. Bunları duyduğu gün ona hiçbir şey söylemediği için pekiştirmiştir."],["15","Ama eğer onları duyduktan sonra geçersiz kılarsa, o zaman kadının suçunu yüklenecektir.”"],["16","Bunlar, erkekle karısı arasında, bir baba ile kızı arasında, gençliğinde kızın babasının evinde olduğunda, Yahve'nin Moşe'ye buyurduğu kurallardır."]],31:[["1","Yahve Moşe'ye şöyle dedi:"],["2","“İsrael'in çocuklarının Midyanlılar'dan öcünü al. Ondan sonra halkına kavuşacaksın.”"],["3","Moşe halka seslenip şöyle dedi: “Midyan'dan Yahve'nin öcünü almak için Midyan'a karşı savaşmak üzere aranızdan adamlar silahlandırın."],["4","Her oymaktan, İsrael'in bütün oymaklarından bin kişiyi savaşa göndereceksiniz.”"],["5","Böylece İsrael binlerinden, her oymaktan bin kişi, savaş için silahlanmış on iki bin kişi teslim edildi."],["6","Moşe, elinde Kutsal Yer'in takımları ve çağrı borularıyla, her oymaktan bin kişiyi kâhin Eleazar oğlu Pinehas'la savaşa gönderdi."],["7","Yahve'nin Moşe'ye buyurduğu gibi Midyan'a karşı savaştılar. Her erkeği öldürdüler."],["8","Midyan krallarını da diğerleriyle birlikte öldürdüler: Beş Midyan kralı Evi, Rekem, Sur, Hur ve Reva'dır. Beor oğlu Balam'ı da kılıçla öldürdüler."],["9","İsrael'in çocukları Midyanlı kadınları çocuklarıyla birlikte esir aldılar; ve bütün hayvanlarını, bütün davarlarını ve bütün mallarını yağmaladılar."],["10","Yaşadıkları yerlerdeki bütün kentleri ve ordugâhlarını ateşe verdiler."],["11","Bütün tutsakları, insan olsun hayvan olsun yağmalanan her şeyi aldılar."],["12","Tutsakları ganimetle birlikte yağmayı Moşe'ye, Kâhin Eleazar'a ve İsrael'in çocukları topluluğuna, Yarden'in yanında, Yeriha'daki Moav ovalarında bulunan ordugâha getirdiler."],["13","Moşe ve Kâhin Eleazar, topluluğun bütün beyleriyle birlikte onları karşılamak için ordugâhın dışına çıktılar."],["14","Moşe, savaş hizmetinden gelen subaylara, binbaşılara, yüzbaşılara öfkelendi."],["15","Moşe onlara şöyle dedi: “Kadınların hepsini sağ mı bıraktınız?"],["16","İşte bunlar, Balam'ın öğüdüyle İsrael'in çocuklarının Peor meselesinde Yahve'ye karşı suç işlemesine neden oldu ve böylece Yahve'nin topluluğu arasında veba oldu."],["17","Şimdi çocuklar arasındaki her erkeği öldürün ve erkekle yatmış, erkek bilen her kadını öldürün."],["18","Yalnız erkekle yatmamış, erkek bilmeyen bütün kızları kendiniz için sağ bırakın.”"],["19","“Yedi gün ordugâhın dışında konaklayın. İnsan öldüren herkes ve öldürülmüş olana dokunan herkes, siz ve esirleriniz üçüncü ve yedinci günde kendinizi arındırın."],["20","Her giysiyi, deriden yapılmış her şeyi, keçi kılından yapılmış her işi ve ağaçtan yapılmış her şeyi arındıracaksınız.”"],["21","Kâhin Eleazar savaşa giden askerlere şöyle dedi: “Yahve'nin Moşe'ye buyurduğu yasanın kuralı budur."],["22","Ancak altını, gümüşü, tuncu, demiri, kalayı ve kurşunu,"],["23","ateşe dayanıklı olan her şeyi ateşten geçireceksiniz ve o temiz olacaktır; yine de kirlilik suyu ile arındırılacaktır. Ateşe dayanamayan her şeyi sudan geçireceksiniz."],["24","Yedinci gün giysilerinizi yıkayacaksınız ve temiz olacaksınız. Ondan sonra ordugâha gireceksiniz.”"],["25","Yahve Moşe'ye şöyle dedi,"],["26","“Sen, kâhin Eleazar ve topluluğun ata evlerinin başları olmak üzere insanlardan ve hayvanlardan alınan ganimeti say;"],["27","ve ganimeti savaşta becerikli, savaşa giden adamlar ile tüm topluluk arasında ikiye böl."],["28","Savaşa çıkan savaşçılardan beş yüzde bir can olmak üzere; insanlardan, sığırlardan, eşeklerden ve sürülerden Yahve için vergi alacaksın."],["29","Onların yarısından alıp Yahve'ye sallamalık sunu olarak kâhin Eleazar'a vereceksin."],["30","İsrael'in çocuklarına düşen yarıdan, insanlardan, sığırlardan, eşeklerden, davarlardan ve bütün hayvanlardan seçilen her elli kişiden birini alıp onları Yahve'nin konutu görevini gerçekleştiren Levililer'e vereceksin.”"],["31","Moşe ve Kâhin Eleazar, Yahve'nin Moşe'ye buyurduğu gibi yaptılar."],["32","Savaşçıların yağmaladığı ganimetin dışında, yağmalananlar arasında altı yüz yetmiş beş bin koyun,"],["33","yetmiş iki bin sığır,"],["34","altmış bir bin eşek,"],["35","ve erkekle yatmamış, erkek bilmeyen kadınlardan toplam otuz iki bin kişi vardı."],["36","Savaşa çıkanların payına düşen yarının sayısı üç yüz otuz yedi bin beş yüz koyundu;"],["37","Yahve'nin koyunlardan aldığı vergi altı yüz yetmiş beşti."],["38","Sığırlar otuz altı bindi; bunlardan Yahve'nin vergisi yetmiş ikiydi."],["39","Eşekler otuz bin beş yüzdü; bunların Yahve'nin vergisi altmış birdi."],["40","On altı bin kişi vardı; bunlardan Yahve'nin vergisi otuz iki kişiydi."],["41","Moşe, Yahve'nin kendisine buyurduğu gibi, Yahve'nin sallamalık sunu olan vergiyi Kâhin Eleazar'a verdi."],["42","Moşe'nin savaşan erkeklerden böldüğü İsrael'in çocuklarının yarısından"],["43","(şimdi topluluğun yarısı üç yüz otuz yedi bin beş yüz koyun,"],["44","otuz altı bin sığır,"],["45","otuz bin beş yüz eşek,"],["46","ve on altı bin kişiydi),"],["47","İsrael'in çocuklarının yarısından, insandan olsun, hayvandan olsun, her elliden çekilmiş olsun birisini, Yahve'nin Moşe'ye buyurduğu gibi Yahve'nin konutu görevini gerçekleştiren Levililer'e verdi."],["48","Ordu binlerinin başındaki subaylar, binbaşılar ve yüzbaşılar Moşe'ye yaklaştı."],["49","Moşe'ye şöyle dediler: “Hizmetkârların, komutamız altındaki askerlerin tamamını aldık; aramızdan tek bir adam bile eksik değil."],["50","Yahve'nin önünde canlarımızın kefareti olsun diye, herkesin bulduğu sunuları, altın takıları, ayak halkaları, bilezikleri, mühür yüzüklerini, küpeleri ve kolyeleri getirdik.”"],["51","Moşe ile Kâhin Eleazar onlardan altınları, işlenmiş mücevherlerin hepsini aldılar."],["52","Binbaşıların ve yüzbaşıların Yahve'ye sundukları sallama sunusu altının tamamı on altı bin yedi yüz elli şekeldi."],["53","Savaşcılar, hepsi kendisi için ganimet almıştı."],["54","Moşe ile Kâhin Eleazar, binbaşılardan ve yüzbaşılardan altını aldılar ve Yahve'nin önünde İsrael'in çocuklarının anılması için Buluşma Çadırı'na getirdiler."]],32:[["1","Ruven'in çocuklarının ve Gad'ın çocuklarının çok sayıda hayvanı vardı. Yazer ülkesini ve Gilad ülkesini gördüler. İşte, o yer hayvanlara göre bir yerdi."],["2","Bunun üzerine Gad'ın çocukları ve Ruven'in çocukları gelip Moşe'ye, Kâhin Eleazar'a ve topluluğun beylerine şöyle dediler:"],["3","“Atarot, Dibon, Yazer, Nimra, Heşbon, Eleale, Sevam, Nevo, ve Beon,"],["4","Yahve'nin İsrael topluluğunun önünde vurduğu ülke, hayvancılık diyarıdır; hizmetkârının da hayvanları var.”"],["5","Onlar, “Eğer senin gözünde lütuf bulduysak, bu diyar mülk olarak hizmetkârlarına verilsin” dediler. “Bizi Yarden'den geçirmeyin.”"],["6","Moşe Gad'ın çocuklarına ve Ruven'in çocuklarına şöyle dedi: “Siz burada otururken kardeşleriniz savaşa mı gidecek?"],["7","İsrael'in çocuklarının yüreğini Yahve'nin kendilerine verdiği ülkeye gitmekten neden vazgeçiriyorsunuz?"],["8","Babalarınızı ülkeyi görmek için Kadeş-Barnea'dan gönderdiğimde öyle yaptılar."],["9","Çünkü Eşkol Vadisi'ne çıkıp ülkeyi gördüklerinde, Yahve'nin kendilerine verdiği ülkeye girmesinler diye, İsrael'in çocuklarının yüreğini yılgınlığa düşürdüler."],["10","O gün Yahve'nin öfkesi alevlendi ve şöyle ant içti:"],["11","'Mısır'dan çıkan yirmi yaş ve üzeri adamlardan hiçbiri, Avraham'a, İshak'a ve Yakov'a ant içtiğim ülkeyi kesinlikle görmeyecekler; çünkü tamamen beni izlemediler,"],["12","Kenizzi Yefunne oğlu Kalev ve Nun oğlu Yeşu dışında, tamamen beni izlemediler; çünkü onlar tamamen Yahve'nin ardınca gittiler.'"],["13","Yahve'nin öfkesi İsrael'e karşı alevlendi ve Yahve'nin gözünde kötülük yapan tüm kuşak tükeninceye dek, kırk yıl onları çölde gezdirdi.”"],["14","“İşte, Yahve'nin İsrael'e karşı öfkesini artırmak için, günahkâr artışıyla, atalarınızın yerine siz kalktınız."],["15","Çünkü onun arkasından dönerseniz, yine onları çölde bırakacaktır; siz de bu insanların hepsini yok edeceksiniz.”"],["16","Onun yanına gelip şöyle dediler: “Burada hayvanlarımız için ağıllar, çocuklarımız için kentler kuracağız;"],["17","ama biz, İsrael'in çocuklarını kendi yerlerine götürünceye kadar, onların önünden gitmek üzere silahlanmış olacağız. Küçüklerimiz bu ülke sakinleri yüzünden surlu kentlerde oturacaklar."],["18","İsrael'in çocuklarının tümü miraslarını alana dek evlerimize dönmeyeceğiz."],["19","Çünkü biz Yarden'in karşı yakasında ve ötesinde miras almayacağız; çünkü mirasımız bize Yarden'in bu yakasında, doğuya doğru düştü.”"],["20","Moşe onlara şöyle dedi: “Eğer bunu yaparsanız, Yahve'nin önünde savaşa gitmek üzere silahlanırsanız,"],["21","silahlı adamlarınızın her biri, düşmanlarını önden kovana dek Yahve'nin önünde Yarden'den geçecek,"],["22","ülke Yahve'nin önünde boyunduruk altına alınınca; sonra geri döneceksiniz ve Yahve'ye ve İsrael'e karşı yükümlülüklerinizden kurtulacaksınız. O zaman bu diyar Yahve'nin önünde sizin mülkünüz olacaktır.”"],["23","“Ama eğer bunu yapmazsanız, işte, Yahve'ye karşı günah işlemiş olursunuz; ve emin olun günahınız sizi bulacaktır."],["24","Çocuklarınız için kentler, koyunlarınız için ağıllar yapın; ve ağzınızdan çıkanı yapın.”"],["25","Gad'ın çocukları ile Ruven'in çocukları Moşe'ye şöyle dediler: “Hizmetkârların efendimin buyurduğu gibi yapacaklar."],["26","Çocuklarımız, karılarımız, davarlarımız ve bütün hayvanlarımız burada, Gilad kentlerinde olacaklar;"],["27","ama efendimin dediği gibi, savaş için silahlanmış olan herkes, hizmetkârların Yahve'nin önünden geçecekler.''"],["28","Bunun üzerine Moşe, Kâhin Eleazar'a, Nun oğlu Yeşu'ya ve İsrael'in çocuklarının boylarının atalar evleri beylerine onlar hakkında buyruk verdi."],["29","Moşe onlara şöyle dedi: “Eğer Gad'ın çocukları ve Ruven'in çocukları, savaşmak üzere silahlanmış olan her adam Yahve'nin önünde sizinle birlikte Yarden'den geçerlerse, ve ülke önünüzde boyunduruk altına alınırsa, o zaman onlara mülk olarak Gilad diyarını vereceksiniz;"],["30","ama eğer silahlı olarak sizinle birlikte geçmezlerse, Kenan ülkesinde aranızda mülkleri olacaktır.”"],["31","Gad'ın çocukları ile Ruven'in çocukları şöyle yanıt verdiler: “Yahve'nin senin hizmetkârlarına söylediği gibi, biz de öyle yapacağız."],["32","Yahve'nin önünde silahlanmış olarak Kenan ülkesine geçeceğiz ve mirasımızın mülkü Yarden'in ötesinde bizde kalacaktır.”"],["33","Moşe onlara, Amorlular'ın kralı Sihon'un krallığını ve Başan Kralı Og'un krallığını; ülkeyi, kentlerine ve sınırlarına göre, kentin çevresindeki arazileriyle, Gad'ın çocuklarına, Ruven'in çocuklarına ve Yosef oğlu Manaşşe'nin yarım oymağına verdi."],["34","Gad'ın çocukları Divon'u, Atarot'u, Aroer'i,"],["35","Atrot-şofan'ı, Yazer'i, Yogveha'yı,"],["36","Beyt-Nimra'yı ve Beyt-Haran'ı kurdular; bunlar surlu kentler ve koyun ağıllarıydı."],["37","Ruven'in çocukları Heşvon'u, Eleale'yi, Kiriatayim'i,"],["38","Nevo'yu, Baal Meon'u (adları değiştirildi) ve Sivma'yı kurdular. Kurdukları kentlere başka adlar verdiler."],["39","Manaşşe oğlu Makir'in çocukları Gilad'a giderek orayı aldılar ve orada yaşayan Amorlular'ın mülklerinden ettiler."],["40","Moşe Gilad'ı Manaşşe oğlu Makir'e verdi; ve orada yaşadı."],["41","Manaşşe oğlu Yair gitti ve onların köylerini aldı ve onlara Havvot Yair adını verdi."],["42","Novah gidip Kenat'ı ve köylerini aldı ve oraya kendi adını, Novah adını verdi."]],33:[["1","İsrael'in çocuklarının Moşe'yle Aron'un eli altında ordularıyla Mısır diyarından çıktıklarında yaptıkları yolculuklar bunlardır."],["2","Moşe Yahve'nin buyruğu uyarınca yolculuklarının başlangıç noktalarını yazdı. Bunlar başlangıç noktalarına göre yolculuklarıdır."],["3","Birinci ayın on beşinci günü Ramses'ten yola çıktılar. Pesah'ın ertesi günü, İsrael'in çocukları tüm Mısırlılar'ın gözü önünde büyük bir el aracılığıyla çıktılar."],["4","Mısırlılar, Yahve'nin aralarında vurduğu ilk doğanların hepsini gömüyordu. Yahve aynı zamanda onların ilâhlarını da yargılamıştı."],["5","İsraelliler Ramses'ten yola çıkıp Sukkot'ta konakladılar."],["6","Sukkot'tan yola çıkıp çölün kıyısındaki Etam'da konakladılar."],["7","Etam'dan yola çıkıp Baal Sefon'un önündeki Pihahirot'a döndüler ve Migdol'un önünde konakladılar."],["8","Hahirot'un önünden yola çıkıp denizin ortasından çöle doğru ilerlediler. Etam çölünde üç günlük bir yol alıp Mara'da konakladılar."],["9","Mara'dan yola çıkıp Elim'e geldiler. Elim'de on iki su kaynağı ve yetmiş palmiye ağacı vardı ve orada konakladılar."],["10","Elim'den yola çıkıp Kızıldeniz'in yanında konakladılar."],["11","Kızıldeniz'den yola çıkıp Sin Çölü'nde konakladılar."],["12","Sin Çölü'nden yola çıkıp Dofka'da konakladılar."],["13","Dofka'dan yola çıkıp Aluş'ta konakladılar."],["14","Aluş'tan yola çıkıp halkın içmesi için suyun olmadığı Refidim'de konakladılar."],["15","Refidim'den yola çıkıp Sina Çölü'nde konakladılar."],["16","Sina Çölü'nden yola çıkıp Kivrot Hattaava'da konakladılar."],["17","Kivrot Hattaava'dan yola çıkıp Haserot'ta konakladılar."],["18","Haserot'tan yola çıkıp Ritma'da konakladılar."],["19","Ritma'dan yola çıkıp Rimmon Peres'te konakladılar."],["20","Rimmon Peres'ten yola çıkıp Livna'da konakladılar."],["21","Livna'dan yola çıkıp Rissa'da konakladılar."],["22","Rissa'dan yola çıkıp Kehelata'da konakladılar."],["23","Kehelata'dan yola çıkıp Şefer Dağı'nda konakladılar."],["24","Şefer Dağı'ndan yola çıkıp Harada'da konakladılar."],["25","Harada'dan yola çıkıp Makhelot'ta konakladılar."],["26","Makhelot'tan yola çıkıp Tahat'ta konakladılar."],["27","Tahat'tan yola çıkıp Terah'ta konakladılar."],["28","Terah'tan yola çıkıp Mitka'da konakladılar."],["29","Mitka'dan yola çıkıp Haşmona'da konakladılar."],["30","Haşmona'dan yola çıkıp Moserot'ta konakladılar."],["31","Moserot'tan yola çıkıp Bene Yaakan'da konakladılar."],["32","Bene Yaakan'dan yola çıkıp Hor Haggidgad'da konakladılar."],["33","Hor Haggidgad'dan yola çıkıp Yotvata'da konakladılar."],["34","Yotvata'dan yola çıkıp Avrona'da konakladılar."],["35","Avrona'dan yola çıkıp Esyon Geber'de konakladılar."],["36","Esyon Geber'den yola çıkıp Zin Çölü'ndeki Kadeş'te konakladılar."],["37","Kadeş'ten yola çıkıp Edom ülkesinin kenarındaki Hor Dağı'nda konakladılar."],["38","Kâhin Aron, İsrael'in çocuklarının Mısır diyarından çıkışının kırkıncı yılında, beşinci ayın, ayın birinci günü, Yahve'nin buyruğu uyarınca Hor Dağı'na çıktı ve orada öldü."],["39","Aron Hor Dağı'nda öldüğünde yüz yirmi üç yaşındaydı."],["40","Güneyde Kenan ülkesinde yaşayan Kenanlı Arad Kralı, İsrael'in çocuklarının geldiğini duydu."],["41","Hor Dağı'ndan yola çıkıp Salmona'da konakladılar."],["42","Salmona'dan yola çıkıp Punon'da konakladılar."],["43","Punon'dan yola çıkıp Ovot'ta konakladılar."],["44","Ovot'tan yola çıkıp Moav sınırındaki İye Avarim'de konakladılar."],["45","İyim'den yola çıkıp Divon Gad'da konakladılar."],["46","Divon Gad'dan yola çıkıp Almon Divlatayim'de konakladılar."],["47","Almon Divlatayim'den yola çıkıp Nevo'nun önündeki Avarim dağlarında konakladılar."],["48","Avarim dağlarından ayrılıp Yarden yanında, Yeriha'daki Moav ovalarında konakladılar."],["49","Yarden yanında, Beyt-Yeşimot'tan Moav ovalarındaki Avel-Şittim'e kadar konakladılar."],["50","Yahve, Moav ovalarında, Yarden yanında, Yeriha'da Moşe'ye şöyle dedi,"],["51","İsrael'in çocuklarına söyle ve onlara de ki: “Yarden'i geçerek Kenan ülkesine girdiğinizde,"],["52","o zaman ülkede oturanların hepsini önünüzden kovacaksınız, bütün taştan putlarını yok edeceksiniz, bütün dökme putlarını yok edeceksiniz, ve tüm yüksek yerlerini yıkacaksınız."],["53","Ülkeyi mülk edinecek ve orada oturacaksınız; çünkü ülkeyi mülk edinmek için size verdim."],["54","Ülkeyi oymaklarınıza göre kurayla miras alacaksınız; daha büyük gruplara daha çok, daha küçük gruplara daha az miras vereceksiniz. Birine kura nereye düşerse, orası onun olacaktır. Atalarınızın oymaklarına göre miras alacaksınız.”"],["55","“Ama eğer ülkede yaşayanları önünüzden kovmazsanız, onlardan geriye bıraktıklarınız gözlerinizde iğne, böğrünüzde diken gibi olacak. İçinde oturduğunuz ülkeden sizi sıkıştıracaklar."],["56","Öyle olacak ki, onlara ne yapmayı düşündümse size de öyle yapacağım.”"]],34:[["1","Yahve Moşe'ye şöyle konuştu:"],["2","“İsrael'in çocuklarına buyur ve onlara söyle: 'Kenan ülkesine girdiğiniz zaman, (burası size miras olarak düşecek olan ülkedir; sınırlarına göre Kenan ülkesi),"],["3","güney sınırınız Zin Çölü'nden Edom kıyısı boyunca olacak ve güney sınırınız Tuz Denizi'nin ucundan doğuya doğru olacak."],["4","Sınırınız Akravvim yokuşunun güneyine doğru dönecek ve Zin'e kadar geçecek; ve Kadeş-Barnea'nın güneyinden geçecek; ve oradan Hazar Addar'a gidecek ve Asmon'a geçecek."],["5","Sınır Asmon'dan Mısır Irmağı'na doğru dönecek ve denizde sona erecektir.'”"],["6","“'Batı sınırında Büyük Deniz ve onun sınırı olacaktır. Burası sizin batı sınırınız olacaktır.'”"],["7","“'Kuzey sınırınız bu olacak; kendinize Büyük Deniz'den Hor Dağı'na kadar işaret koyacaksınız."],["8","Hor Dağı'ndan Hama'nın girişine doğru işaret koyacaksınız; sınır Sedad'ın yanından geçecek."],["9","Ondan sonra sınır Sifron'a gidecek ve Hazar Enan'da son bulacak. Bu sizin kuzey sınırınız olacaktır.'”"],["10","“'Doğu sınırınızı Hazar Enan'dan Şefam'a kadar işaret koyacaksınız."],["11","Sınır Şefam'dan Ain'in doğusundaki Rivla'ya kadar inecek. Sınır aşağıya inecek ve doğuya doğru Kinneret Denizi kıyısına kadar ulaşacak."],["12","Sınır Yarden'e kadar inecek ve Tuz Denizi'nde son bulacaktır. Çevresindeki sınırlarına göre bu sizin ülkeniz olacaktır.'”"],["13","Moşe İsrael'in çocuklarına buyruk verip şöyle dedi: “Bu, kurayla miras alacağınız Yahve'nin dokuz buçuk oymağa verilmesini buyurmuş olduğu ülkedir;"],["14","atalarının evlerine göre Ruven'in çocukları oymağı, atalarının evlerine göre Gad'ın çocukları oymağı ve Manaşşe oymağının yarısı miraslarını aldılar."],["15","İki oymakla yarım oymak miraslarını Yarden'in ötesinde, doğuda, gün doğusuna doğru Yeriha'da aldılar.”"],["16","Yahve Moşe'ye şöyle dedi:"],["17","“Ülkeyi miras olarak size bölecek olan adamların adları şunlardır: Kâhin Eleazar ve Nun oğlu Yeşu."],["18","Ülkeyi miras olarak bölmek üzere her oymaktan bir bey alacaksın."],["19","O adamların adları şunlardır: Yahuda oymağından Yefunne oğlu Kalev."],["20","Şimon'un çocukları oymağından Ammihud oğlu Şemuel."],["21","Benyamin oymağından Kislon oğlu Elidad."],["22","Dan'ın çocukları oymağından bey olarak, Yogli oğlu Bukki."],["23","Yosef'in çocuklarından: Manaşşe'nin çocukları oymağından bey olarak, Efod oğlu Hanniel."],["24","Efraim'in çocukları oymağından bey olarak, Şiftan oğlu Kemuel."],["25","Zevulun'un çocukları oymağından bey olarak, Parnak oğlu Elisafan."],["26","İssakar'ın çocukları oymağından bey olarak, Azzan oğlu Paltiel."],["27","Aşer'in çocukları oymağından bey olarak, Şelomi oğlu Ahihud."],["28","Naftali'nin çocukları oymağından bey olarak, Ammihud oğlu Pedahel.”"],["29","Kenan ülkesinde İsrael'in çocuklarına mirası bölmek için Yahve'nin buyurduğu kişiler bunlardır."]],35:[["1","Yahve, Moav ovalarında, Yarden yanında, Yeriha'da Moşe'ye şöyle dedi,"],["2","“İsrael'in çocuklarına buyur, miraslarından oturmaları için Levililer'e kentler versinler. Kentler için onların çevresinde Levililer'e otlaklar vereceksiniz."],["3","İçinde oturmak için kentleri olacak. Onların otlakları hayvanları, malları ve bütün sığırları için olacaktır."],["4","“Levililer'e vereceğiniz kentlerdeki otlaklar kentin surlarından başlayıp çevresine doğru bin arşın olacak."],["5","Kentin ortada olmak üzere, kentin dışını doğu tarafı için iki bin arşın, güney tarafı için iki bin arşın, batı tarafı için iki bin arşın, kuzey tarafı için iki bin arşın ölçeceksiniz. Bu onların kentlerinin otlakları olacaktır.”"],["6","“Levililer'e vereceğiniz kentler, adam öldüren insanın oraya kaçması için vereceğiniz altı sığınak kent olacaktır. Bunların dışında kırk iki kent vereceksiniz."],["7","Levililer'e vereceğiniz kentlerin tümü, otlaklarıyla birlikte kırk sekiz kent olacaktır."],["8","İsrael'in çocuklarına mülk olarak vereceğiniz kentlerin çoğundan çoğunu, azından da azını alacaksınız. Herkes miras aldığı mirasa göre kentlerinden bazılarını Levililer'e verecek."],["9","Yahve Moşe'ye şöyle konuştu:"],["10","“İsrael'in çocuklarına söyle ve onlara de: Yarden'i aşıp Kenan ülkesine girdiğinizde,"],["11","ondan sonra kendinize sığınacak kentler olarak kentler atayacaksınız; kasıtsız birini öldüren kişi oraya kaçabilecektir."],["12","Kentler sizin için öç alandan sığınacağınız yer olacak; öyle ki, adam öldüren kişi yargılanmak üzere topluluğun önüne çıkana dek ölmesin."],["13","Vereceğiniz kentler sizin için altı sığınak kent olacak."],["14","Yarden'in ötesinde üç kent vereceksiniz ve Kenan ülkesinde de üç kent vereceksiniz. Bunlar sığınma kentleri olacaklar."],["15","Bu altı kent İsrael'in çocuklarına, gariplere ve aralarında yaşayan yabancılara sığınak olacak; öyle ki, kasıtsız birini öldüren herkes oraya kaçabilsin.”"],["16","“'Ama eğer onu demir bir aletle vurmuş ve o ölmüşse, o katildir. Katil kesinlikle öldürülecektir."],["17","Eğer elindeki bir adamı öldürebilecek bir taşla onu vurmuş ve o ölmüşse, o katildir. Katil kesinlikle öldürülecektir."],["18","Ya da insanı öldürebilecek elindeki ağaçtan bir silahla ona vurmuş ve o ölmüşse, o katildir. Katil kesinlikle öldürülecektir."],["19","Kan öcü alan, katili kendisi öldürecektir. Onunla karşılaştığında onu öldürecektir."],["20","Eğer kinden dolayı onu iterse, ya da pusuya yatıp ona bir şey fırlatmışsa ve o ölmüşse,"],["21","ya da düşmanlıkla ona eliyle vurmuşsa ve o ölmüşse, ona vuran kişi kesinlikle öldürülecektir. O katildir. Kan öcünü alan, katille karşılaştığında onu öldürecektir.'”"],["22","“'Ama eğer onu ansızın düşmanlık olmadan iterse, ya da pusuya yatmadan üzerine bir şey fırlatmışsa,"],["23","ya da görmeden üstüne insanın ölebileceği bir taş atmış ve o ölmüşse, onun düşmanı olmadan zararını aramamışsa,"],["24","o zaman topluluk, vuranla kan öcünü alan arasında bu hükümlere göre hüküm verecektir."],["25","Topluluk, adam öldüren kişiyi kan öcü alanın elinden kurtaracak ve topluluk onu kaçtığı sığınma kentine geri gönderecektir. Kutsal yağla meshedilen başkâhinin ölümüne dek orada oturacaktır.'”"],["26","“'Ama adam öldüren kişi herhangi bir zamanda kaçmış olduğu sığındığı kentin sınırlarının dışına çıkarsa,"],["27","kan öcünü alan kişi de onu sığındığı kentin sınırının dışında bulur ve kan öcü alan onu öldürürse, o kişi kandan suçlu olmayacaktır,"],["28","çünkü onun başkâhinin ölümüne dek sığındığı kentte kalması gerekirdi. Yalnız başkâhinin ölümünden sonra, adam öldüren kişi kendi mülkü olan diyara geri dönecektir.'”"],["29","“'Bunlar, tüm konutlarınızda kuşaklar boyunca sizin için kural ve ilke olacaktır.'”"],["30","“'Kim bir insanı öldürürse, katil tanıkların ifadesine göre öldürülecektir; ancak bir tanık, herhangi bir insanın ölmesine karşı tek başına tanıklık etmeyecektir.'”"],["31","“'Ölüm suçlusu katilin hayatı için de fidye almayacaksınız. Kesinlikle öldürülecektir.'”"],["32","“'Kâhinin ölümünden önce tekrar gelip diyarda otursun diye sığındığı kente kaçan kişiden fidye almayacaksınız.'”"],["33","“'Yaşadığınız ülkeyi kirletmeyeceksiniz; çünkü kan ülkeyi kirletir. Ülke içinde dökülen kanın kefareti ancak onu dökenin kanı ile olur."],["34","Oturduğunuz ve benim oturduğum ülkeyi kirletmeyeceksiniz; çünkü ben, Yahve, İsrael'in çocukları arasında oturuyorum.'”"]],36:[["1","Yosef'in oğulları soylarından Manaşşe oğlu Makir oğlu, Gilad'ın oğulları soyundan atalar evleri beyleri yaklaştılar ve Moşe'nin önünde ve İsrael'in çocuklarının atalar evleri başları olan beylerin önünde konuştular."],["2","Onlar şöyle dediler: “Yahve efendime, bu toprakları kurayla İsrael'in çocuklarına miras olarak vermesini buyurdu. Efendime Yahve tarafından kardeşimiz Selofhad'ın mirasını kızlarına vermesi buyruldu."],["3","İsrael'in çocuklarından başka oymakların oğullarından biriyle evlenirlerse, o zaman onların mirası atalarımızın mirasından alınacak ve ait olacakları oymağın mirasına katılacak. Böylece mirasımızın kurasından alınmış olacak."],["4","İsrael'in çocuklarının Jübile'si geldiğinde, onların mirası ait olacakları oymağın mirasına katılacak. Böylece onların mirası atalarımızın oymağının mirasından alınacak.”"],["5","Moşe, Yahve'nin sözüne göre İsrael'in çocuklarına şu buyruğu verdi: “Yosefoğulları oymağı doğru söylüyor."],["6","Selofhad'ın kızları hakkında Yahve'nin buyurup söylediği şey şudur: Onlar en iyisinin kim olduğunu düşünüyorsa onunla evlensinler, yalnız babalarının oymağının soyu içinde evlenecekler."],["7","Böylece İsrael'in çocuklarının mirası oymaktan oymağa geçmeyecek; çünkü İsrael'in çocuklarının hepsi atalarının oymağının mirasını koruyacaklar."],["8","İsrael'in çocuklarından herhangi bir oymağında mirasa sahip olan her kız, babasının oymağının soyundan birine eş olacak; böylece İsrael'in çocuklarının her biri atalarının mirasına sahip olabilecekler."],["9","Böylece miras bir oymaktan diğerine geçmeyecektir; çünkü İsrael'in çocuklarının oymaklarının her biri kendi mirasını koruyacaktır.”"],["10","Selofhad'ın kızları, Yahve'nin Moşe'ye buyurduğu gibi yaptı:"],["11","Çünkü Selofhad'ın kızları Mahlah, Tirsa, Hoglah, Milka ve Noa, babalarının kardeşinin oğullarıyla evlendiler."],["12","Yosef oğlu Manaşşe'nin oğullarının soyları içinde evlendiler. Mirasları atalarının soyunun oymağında kaldı."],["13","Bunlar, Yahve'nin Moşe aracılığıyla Yarden yanında Yeriha'daki Moav ovalarında İsrael'in çocuklarına buyurduğu buyruk ve kurallardır."]]};export{a as default};
